Object.assign(window.TEM8_DICTIONARY, {"whereby":{"media":{"uk":"media/uk/whereby__gb_1.mp3","us":"media/us/whereby__us_1.mp3"},"oxford":{"phon":"weəˈbaɪ","pos":"adverb","senses":[{"en":"by which; because of which","cn":"凭此；借以；由于","ex":{"en":"They have introduced a new system whereby all employees must undergo regular training.","cn":"他们采用了新的制度，所有的雇员都必须定期培训。"}}]},"collins":{"senses":[{"pos":"PRON-REL 关系代词","cn":"凭此;借以","en":"A system or action whereby something happens is one that makes that thing happen.","ex":{"en":"...the system whereby Britons choose their family doctors and the government pays those doctors","cn":"通过这个系统，英国人选择自己的家庭医生，而由政府给那些医生支付薪水"}}]},"examples":[{"en":"They have introduced a new system whereby all employees must undergo regular training.","cn":"他们采用了新的制度，所有的雇员都必须接受正规的培训。"},{"en":"a proposal whereby EU citizens would be allowed to reside anywhere in the EU","cn":"允许欧盟公民在欧盟任何地方居住的一项提议"}]},"whether":{"media":{"uk":"media/uk/whether__gb_1.mp3","us":"media/us/whether__us_1.mp3"},"oxford":{"phon":"ˈweðə(r)","pos":"conjunction","senses":[{"en":"used to express a doubt or choice between two possibilities","cn":"（表示迟疑或两个可能性之间的选择）是否","ex":{"en":"He seemed undecided whether to go or stay.","cn":"他似乎还没有决定去留。"}},{"en":"used to show that something is true in either of two cases","cn":"（表示两种情况都真实）是…（还是），或者…（或者），不管…（还是）","ex":{"en":"You are entitled to a free gift whether you accept our offer of insurance or not.","cn":"无论你接不接受我们的保险提议，你都可以免费得到一份礼物。"}}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"(表示选择或怀疑)是否，是不是","en":"You use whether when you are talking about a choice or doubt between two or more alternatives.","ex":{"en":"To this day, it's unclear whether he shot himself or was murdered","cn":"至今尚不清楚他究竟是饮弹自杀还是被谋杀。"}},{"pos":"CONJ-SUBORD 连词","cn":"无论;不管","en":"You use whether to say that something is true in any of the circumstances that you mention.","ex":{"en":"This happens whether the children are in two-parent or one-parent families","cn":"不管孩子是生活在双亲还是单亲家庭，这种情况都会发生。"}}]},"examples":[{"en":"You are entitled to a free gift whether you accept our offer of insurance or not.","cn":"无论你接不接受我们的保险提议，你都可以免费得到一份礼物。"},{"en":"I asked him whether he had done it all himself or whether someone had helped him.","cn":"我问过他这都是他自己做的还是有人帮他做的。"}]},"whistling":{"lemma":"whistle"},"whine":{"media":{"uk":"media/uk/whine__gb_1.mp3","us":"media/us/whine__us_1.mp3"},"oxford":{"phon":"waɪn","pos":"verb","senses":[{"en":"to complain in an annoying, crying voice","cn":"哭哭啼啼；哭嚷","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"Stop whining!","cn":"别哭哭啼啼的！"}},{"en":"to make a long, high, unpleasant sound because you are in pain or unhappy","cn":"哀鸣；惨叫","g":"[intransitive]","ex":{"en":"The dog whined and scratched at the door.","cn":"那狗嗷嗷地叫着抓门。"}},{"en":"to make a long, high, unpleasant sound","cn":"嘎嘎响；嗖嗖响；嘎吱嘎吱响","g":"[intransitive]","ex":{"en":"The engines whined softly in the background.","cn":"发动机在背后发出轻微的嘎嘎声。"}},{"en":"a long, high sound that is usually unpleasant or annoying","cn":"嘎吱声；吱吱声；嘎嘎声","ex":{"en":"the steady whine of the engine","cn":"发动机不停的嘎吱声"},"pos":"noun"},{"en":"a long, high sound that a child or dog makes when it is hurt or wants something","cn":"（儿童的）哭喊声；（狗的）号叫声","pos":"noun"},{"en":"a high tone of voice that you use when you complain about something","cn":"抱怨的语调","ex":{"en":"Her voice took on a nasal whine of complaint.","cn":"她的声音带着抱怨的鼻音。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"尖叫;哀号;悲鸣","en":"If something or someone whines, they make a long, high-pitched noise, especially one which sounds sad or unpleasant.","ex":{"en":"He could hear her dog barking and whining in the background","cn":"他能听见她的狗在暗处吠叫、哀嚎。"}},{"pos":"VERB 动词","cn":"（令人讨厌地）抱怨;唠叨","en":"If you say that someone is whining, you mean that they are complaining in an annoying way about something unimportant.","ex":{"en":"They come to me to whine about their troubles.","cn":"他们到我这儿来不停地唠叨他们的烦恼。"}}]},"examples":[{"en":"‘I want to go home,’ whined Toby. “","cn":"我要回家。”托比哭嚷道。"},{"en":"The dog whined and scratched at the door.","cn":"那狗嗷嗷地叫着抓门。"}]},"wheeled":{"lemma":"wheel","media":{"uk":"media/ldoce/hwd/bre/4/wheeled0205.mp3","us":"media/ldoce/hwd/ame/4/ld41wheeled.mp3"}},"whirl":{"oxford":{"phon":"wɜːl","pos":"verb","senses":[{"en":"to move, or make somebody/something move, around quickly in a circle or in a particular direction","cn":"（使）旋转，回旋，打转","g":"[intransitive, transitive]","ex":{"en":"Leaves whirled in the wind.","cn":"落叶在风中旋转。"}},{"en":"if your mind, thoughts, etc. whirl, you feel confused and excited and cannot think clearly","cn":"（头脑、思想等）混乱不清，激动，恍惚","g":"[intransitive]","ex":{"en":"I couldn't sleep—my mind was whirling from all that had happened.","cn":"我睡不着，所发生的一切一直在脑子里转来转去。"}},{"en":"a movement of something turning round and round","cn":"旋转；回旋；急转","lab":"figurative","ex":{"en":"a whirl of dust","cn":"尘土飞扬"},"pos":"noun"},{"en":"a number of activities or events happening one after the other","cn":"接连不断的活动；纷至沓来的事件","ex":{"en":"Her life was one long whirl of parties.","cn":"她的生活就是接连不断的聚会。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)回旋;(使)旋转","en":"If something or someone whirls around or if you whirl them around, they move around or turn around very quickly.","ex":{"en":"Not receiving an answer, she whirled round","cn":"没有得到答案，她飞快地转过身去。"}},{"pos":"N-COUNT 可数名词","cn":"一连串;接连不断的活动","en":"You can refer to a lot of intense activity as a whirl of activity.","ex":{"en":"In half an hour's whirl of activity she does it all","cn":"经过半个小时的忙碌，她全都做完了。"}},{"pos":"PHRASE 短语","cn":"混乱;躁动","en":"If a person or their mind is in a whirl, they are very confused or excited.","ex":{"en":"My thoughts are in a whirl.","cn":"我的脑子里一团乱。"}},{"pos":"PHRASE 短语","cn":"试一试;尝试一下","en":"If you decide to give an activity a whirl, you do it even though it is something that you have never tried before.","ex":{"en":"Why not give acupuncture a whirl?","cn":"为什么不试试针灸？"}}]},"media":{"uk":"media/uk/whirl__gb_1.mp3","us":"media/us/whirl__us_1.mp3"},"examples":[{"en":"I couldn't sleep — my mind was whirling from all that had happened.","cn":"我睡不着，所发生的一切一直在脑子里转来转去。"},{"en":"Tom whirled her across the dance floor.","cn":"汤姆拥着她从舞池的一边旋转到另一边。"}]},"who":{"media":{"uk":"media/uk/who__gb_1.mp3","us":"media/us/who__us_1.mp3"},"oxford":{"phon":"huː","pos":"pronoun","senses":[{"en":"used in questions to ask about the name, identity or function of one or more people","cn":"（询问姓名、身份或职务）谁，什么人","ex":{"en":"Who is that woman?","cn":"那个女的是谁？"}},{"en":"used to show which person or people you mean","cn":"（表示所指的人）","ex":{"en":"The people who called yesterday want to buy the house.","cn":"昨天打电话来的人想买这座房子。"}},{"en":"used to give more information about somebody","cn":"（进一步提供有关某人的信息）","ex":{"en":"Mrs Smith, who has a lot of teaching experience at junior level, will be joining the school in September.","cn":"史密斯太太将在九月份加入这所学校，她在初级教育方面颇有经验。"}},{"en":"World Health Organization (an international organization that aims to fight and control disease)","cn":"世界卫生组织","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"QUEST 疑问词","cn":"(用于疑问句，询问人的姓名或身份)谁","en":"You use who in questions when you ask about the name or identity of a person or group of people.","ex":{"en":"Who's there?","cn":"谁在哪儿？"}},{"pos":"CONJ-SUBORD 连词","cn":"(尤用在动词和形容词后引导从句，说明人的身份)谁","en":"You use who after certain words, especially verbs and adjectives, to introduce a clause where you talk about the identity of a person or a group of people.","ex":{"en":"Police have not been able to find out who was responsible for the forgeries","cn":"警方还未能查明谁是这些造假案的元凶。"}},{"pos":"PRON-REL 关系代词","cn":"(用于进行限定说明或提供更多信息的关系从句的句首)","en":"You use who at the beginning of a relative clause when specifying the person or group of people you are talking about or when giving more information about them.","ex":{"en":"There are those who eat out for a special occasion, or treat themselves","cn":"有些人会在特殊的日子或犒劳自己时出去吃饭。"}}]},"examples":[{"en":"Mrs Smith, who has a lot of teaching experience at junior level, will be joining the school in September.","cn":"史密斯太太将在九月份加入这所学校，她在初级教育方面颇有经验。"},{"en":"The people (who) we met in France have sent us a card.","cn":"我们在法国结识的人给我们寄来了一张贺卡。"}]},"whiff":{"media":{"uk":"media/uk/whiff__gb_1.mp3","us":"media/us/whiff__us_1.mp3"},"oxford":{"phon":"wɪf","pos":"noun","senses":[{"en":"a smell, especially one that you only smell for a short time","cn":"一点儿气味；一股气味","ex":{"en":"a whiff of cigar smoke","cn":"一股雪茄烟味"}},{"en":"a slight sign or feeling of something","cn":"轻微的迹象（或感觉）；一点点；些许","ex":{"en":"a whiff of danger","cn":"一点点危险"}},{"en":"an unsuccessful attempt to hit the ball","cn":"挥空棒（击球未中）","lab":"North American English"},{"en":"to smell bad","cn":"有臭味；发臭","g":"[intransitive]","lab":"British English, informal，，","pos":"verb"},{"en":"to try without success to hit the ball","cn":"挥空棒（击球未中）","g":"[intransitive]","lab":"North American English","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一阵(气味)","en":"If there is a whiff of a particular smell, you smell it only slightly or only for a brief period of time, for example as you walk past someone or something.","ex":{"en":"He caught a whiff of her perfume.","cn":"他闻到了她身上的一股香水味。"}},{"pos":"N-COUNT 可数名词","cn":"轻微的征兆;迹象","en":"A whiff of something bad or harmful is a slight sign of it.","ex":{"en":"Not a whiff of scandal has ever tainted his private life","cn":"他的私生活没有爆出过一丁点儿的丑闻。"}}]},"examples":[{"en":"He caught a whiff of perfume as he leaned towards her.","cn":"他探身靠近她时闻到一股香水味。"},{"en":"a whiff of cigar smoke","cn":"一股雪茄烟味"}]},"whole":{"media":{"uk":"media/uk/whole__gb_1.mp3","us":"media/us/whole__us_1.mp3"},"oxford":{"phon":"həʊl","pos":"adjective","senses":[{"en":"full; complete","cn":"全部的；整体的；完全的；所有的","g":"[only before noun]","ex":{"en":"Let's forget the whole thing.","cn":"咱们彻底忘掉这件事吧。"}},{"en":"used to emphasize how large or important something is","cn":"（强调大小或重要性）整个的，全部的","g":"[only before noun]","ex":{"en":"I'm going to be talking about a whole range of things today.","cn":"我今天要谈方方面面的事情。"}},{"en":"not broken or damaged","cn":"完整的；完好无损的","ex":{"en":"Owls usually swallow their prey whole (= without biting it into small pieces).","cn":"猫头鹰通常把猎物囫囵吞下。"}},{"en":"all that there is of something","cn":"全部；全体；所有","g":"[singular]","ex":{"en":"The scheme would cover the whole of the UK.","cn":"这一计划将覆盖整个英国。"},"pos":"noun"},{"en":"a thing that is complete in itself","cn":"整个；整体","g":"[countable]","ex":{"en":"Four quarters make a whole.","cn":"四个四分之一构成一个整体。"},"pos":"noun"},{"en":"completely new/different","cn":"全新的；完全不同的","ex":{"en":"It's a whole new world out here.","cn":"这儿是一个全新的世界。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"QUANT 数量词","cn":"全部;整体","en":"If you refer to the whole of something, you mean all of it.","ex":{"en":"He has said he will make an apology to the whole of Asia for his country's past behaviour","cn":"他已表示要为自己国家过去的行径向全亚洲道歉。"}},{"pos":"N-COUNT 可数名词","cn":"(包含几个不同部分的)整体","en":"A whole is a single thing which contains several different parts.","ex":{"en":"An atom itself is a complete whole, with its electrons, protons and neutrons and other elements","cn":"一个原子本身就是一个完整的整体，包括电子、质子、中子及其他元素。"}},{"pos":"ADJ 形容词","cn":"完好的;完整的","en":"If something is whole, it is in one piece and is not broken or damaged.","ex":{"en":"Much of the temple was ruined, but the front was whole, as well as a large hall behind it","cn":"庙宇的大部分都被毁坏了，但其正面及后面的大厅还保存完好。"}},{"pos":"ADV 副词","cn":"(表示强调)完全地","en":"You use whole to emphasize what you are saying.","ex":{"en":"It was like seeing a whole different side of somebody","cn":"这就像是看到一个人完全不同的一面。"}},{"pos":"PHRASE 短语","cn":"整体而言;总体上","en":"If you refer to something as a whole, you are referring to it generally and as a single unit.","ex":{"en":"He described the move as a victory for the people of South Africa as a whole","cn":"他把这一举动描述成整个南非人民的胜利。"}},{"pos":"PHRASE 短语","cn":"大体上说;总的说来","en":"You use on the whole to indicate that what you are saying is true in general but may not be true in every case, or that you are giving a general opinion or summary of something.","ex":{"en":"On the whole, people miss the opportunity to enjoy leisure","cn":"总的来说，人们渴望享受闲暇的时光。"}}]},"examples":[{"en":"The festival will be great for our city and for the country as a whole.","cn":"这次庆典活动对我们城市乃至整个国家都将是意义重大的。"},{"en":"We offer a whole variety of weekend breaks.","cn":"我们提供的周末假日活动丰富多彩，一应俱全。"}]},"whirling":{"lemma":"whirl"},"whistle":{"oxford":{"phon":"ˈwɪsl","pos":"noun","senses":[{"en":"a small metal or plastic tube that you blow to make a loud, high sound, used to attract attention or as a signal","cn":"哨子","ex":{"en":"The referee finally blew the whistle to stop the game.","cn":"主裁判终于吹停了比赛。"}},{"en":"the sound made by blowing a whistle","cn":"哨子声","ex":{"en":"He scored the winning goal just seconds before the final whistle.","cn":"他就在终场哨声前的几秒钟内打进了制胜的一球。"}},{"en":"the sound that you make by forcing your breath out when your lips are almost closed","cn":"口哨","ex":{"en":"He gave a low long whistle of surprise.","cn":"他惊愕地轻轻长吹了声口哨。"}},{"en":"the loud, high sound produced by air or steam being forced through a small opening, or by something moving quickly through the air","cn":"汽笛声；警笛声；呼啸声","ex":{"en":"the whistle of a boiling kettle","cn":"水壶沸腾的声音"}},{"en":"a piece of equipment that makes a loud, high sound when air or steam is forced through it","cn":"汽笛","ex":{"en":"The train whistle blew as we left the station.","cn":"我们离开车站时火车的汽笛响了。"}},{"en":"to make a high sound or a musical tune by forcing your breath out when your lips are almost closed","cn":"吹口哨；打呼哨","g":"[transitive, intransitive]","ex":{"en":"to whistle a tune","cn":"用口哨吹曲子"},"pos":"verb"},{"en":"to make a loud, high sound by blowing into a whistle","cn":"吹哨子","g":"[intransitive]","ex":{"en":"The referee whistled for a foul.","cn":"裁判吹哨子示意有人犯规。"},"pos":"verb"},{"en":"to make a loud, high sound","cn":"鸣响；呼啸；发出笛声","g":"[intransitive]","ex":{"en":"The kettle began to whistle.","cn":"烧水壶呜呜地响了起来。"},"pos":"verb"},{"en":"to move quickly, making a loud, high sound","cn":"呼啸而行；嗖嗖地移动","g":"[intransitive]","ex":{"en":"The wind whistled down the chimney.","cn":"风飕飕地灌进烟囱。"},"pos":"verb"},{"en":"to make a high sound","cn":"啭鸣；唧啾","g":"[intransitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"吹口哨；用口哨吹出(曲调)","en":"When you whistle or when you whistle a tune, you make a series of musical notes by forcing your breath out between your lips, or your teeth.","ex":{"en":"He whistled and sang snatches of songs","cn":"他吹口哨并唱了几段小曲。"}},{"pos":"VERB 动词","cn":"(吃惊、唤狗、赞叹等时)发出口哨声","en":"When someone whistles, they make a sound by forcing their breath out between their lips or their teeth. People sometimes whistle when they are surprised or shocked, or to call a dog, or to show that they are impressed.","ex":{"en":"He whistled, surprised but not shocked","cn":"他吹了声口哨，很是惊讶但没有被吓住。"}},{"pos":"VERB 动词","cn":"(火车)鸣汽笛；(水开时水壶)发出尖啸声","en":"If something such as a train or a kettle whistles, it makes a loud, high sound.","ex":{"en":"Somewhere a train whistled","cn":"不知哪里的火车在鸣汽笛。"}},{"pos":"VERB 动词","cn":"(风、子弹等)呼啸而过","en":"If something such as the wind or a bullet whistles somewhere, it moves there, making a loud, high sound.","ex":{"en":"The wind was whistling through the building","cn":"风呼啸着穿过大楼。"}},{"pos":"N-COUNT 可数名词","cn":"(空气或液流通过狭窄孔洞时发出的)呼啸声;(物体在空气中快速移动时的)呼呼声","en":"A whistle is a loud sound produced by air or steam being forced through a small opening, or by something moving quickly through the air.","ex":{"en":"Hugh listened to the whistle of a train.","cn":"休听着火车呼啸而过。"}},{"pos":"N-COUNT 可数名词","cn":"哨子","en":"A whistle is a small metal tube which you blow in order to produce a loud sound and attract someone's attention.","ex":{"en":"On the platform, the guard blew his whistle","cn":"平台上的警卫吹响了哨子。"}},{"pos":"N-COUNT 可数名词","cn":"上下班的哨声","en":"Some factories and other places where people work have a whistle which signals the beginning and the end of the working day.","ex":{"en":"Every night you could hear the whistles of the steel mill.","cn":"每晚你都会听见炼钢厂的下班哨声。"}},{"pos":"N-COUNT 可数名词","cn":"口哨(一种乐器)","en":"A whistle is a simple musical instrument in the shape of a metal pipe with holes."},{"pos":"PHRASE 短语","cn":"(尤指向当权者)告发，揭发","en":"If you blow the whistle on someone, or on something secret or illegal, you tell another person, especially a person in authority, what is happening.","ex":{"en":"Companies should protect employees who blow the whistle on dishonest workmates and work practices.","cn":"公司应该保护那些检举不诚实的工友及工作行为的员工。"}},{"pos":"PHRASE 短语","cn":"得不到;徒然想得到","en":"If you say that someone can whistle for a particular thing, you mean that you are not willing or able to give it to them.","ex":{"en":"'He wants a police escort.' — 'Well, he can whistle for that.'","cn":"“他希望有警卫护送。”——“那他是指望不上了。”"}},{"pos":"PHRASE 短语","cn":"非常清洁","en":"If you describe something as clean as a whistle, you mean that it is completely clean."},{"pos":"PHRASE 短语","cn":"无错的;问心无愧的","en":"If you describe someone as clean as a whistle, you mean that they are not guilty of having done anything wrong.","ex":{"en":"'His private life is as clean as a whistle,' says McSmith.","cn":"“他的私生活没有任何污点，”麦克史密斯说。"}},{"pos":"PHRASE 短语","cn":"借吹口哨壮胆;故作镇定","en":"If you say that someone is whistling in the dark, you mean that they are trying to remain brave and convince themselves that the situation is not as bad as it seems.","ex":{"en":"Then I waited, trying not to feel as if I were whistling in the dark, but I experienced no easing of my fear and anxiety.","cn":"之后我开始等待，并竭力保持镇定，可是恐惧和焦虑却丝毫没有消减。"}},{"pos":"PHRASE 短语","cn":"喝一杯(酒)","en":"To wet your whistle means to have a drink."},{"pos":"PHRASE 短语","cn":"徒然无功","en":"If you describe someone as whistling in the wind, you mean that they are trying unsuccessfully to change something which cannot be changed.","ex":{"en":"The leader of the Liberal Democrats accused the Prime Minister of whistling in the wind to raise Conservative party morale.","cn":"自由民主党领导人指责首相鼓舞保守党士气之举根本就是徒劳。"}}]},"media":{"uk":"media/uk/whistle__gb_1.mp3","us":"media/us/whistle__us_1.mp3","img":["media/ldoce/img/whistle.jpg"]},"examples":[{"en":"He scored the winning goal just seconds before the final whistle.","cn":"他就在终场哨声前的几秒钟内打进了制胜的一球。"},{"en":"The crowd booed and whistled as the player came onto the field.","cn":"那队员上场时，人群又是发出呸呸声又是吹口哨。"}]},"wheat":{"media":{"img":["media/pic/cereals_comp.jpg","media/thumb/wheat.jpg"],"uk":"media/uk/wheat__gb_1.mp3","us":"media/us/wheat__us_1.mp3"},"oxford":{"phon":"wiːt","pos":"noun","senses":[{"en":"a plant grown for its grain that is used to produce the flour for bread, cakes, pasta, etc.; the grain of this plant","cn":"小麦；小麦粒","lab":"North American English","ex":{"en":"wheat flour","cn":"小麦制的面粉"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"小麦(指植物或籽实)","en":"Wheat is a cereal crop grown for food. Wheat is also used to refer to the grain of this crop, which is usually ground into flour and used to make bread. to separate the wheat from the chaff→see: ;","ex":{"en":"...farmers growing wheat, corn, or other crops.","cn":"种植小麦，玉米或其他农作物的农民。"}}]},"examples":[{"en":"wheat flour","cn":"小麦制的面粉"},{"en":"a field of wheat","cn":"一片麦地"}]},"where":{"media":{"uk":"media/uk/where__gb_1.mp3","us":"media/us/where__us_1.mp3"},"oxford":{"phon":"weə(r)","pos":"adverb","senses":[{"en":"in or to what place or situation","cn":"在哪里；到哪里；处于哪种情形","ex":{"en":"Where do you live?","cn":"你住在哪儿？"}},{"en":"used after words or phrases that refer to a place or situation to mean ‘at, in or to which’","cn":"（用于表示地点或情况的词语后）在那（地方），到那（地方）","ex":{"en":"It's one of the few countries where people drive on the left.","cn":"这是为数不多的几个靠左行驶的国家之一。"}},{"en":"the place or situation in which","cn":"在那里；在该处；在该情况下","ex":{"en":"We then moved to Paris, where we lived for six years.","cn":"我们随后移居巴黎，在那里住了六年。"}},{"en":"(in) the place or situation in which","cn":"（在）…的地方；（在）…情况下","ex":{"en":"This is where I live.","cn":"这是我住的地方。"},"pos":"conjunction"}]},"collins":{"senses":[{"pos":"QUEST 疑问词","cn":"（用于疑问句）在哪里，从哪里，到哪里","en":"You use where to ask questions about the place something is in, or is coming from or going to.","ex":{"en":"Where did you meet him?","cn":"你在哪里见过他？"}},{"pos":"CONJ-SUBORD 连词","cn":"(尤用于动词和形容词后引导从句，表示某物所在或某事发生的地点)那里，那儿","en":"You use where after certain words, especially verbs and adjectives, to introduce a clause in which you mention the place in which something is situated or happens.","ex":{"en":"People began looking across to see where the noise was coming from","cn":"人们开始四下察看，想弄清楚那声响来自何处。"}},{"pos":"QUEST 疑问词","cn":"(用于疑问句)在哪一地点,在哪一阶段，在哪方面","en":"You use where to ask questions about a situation, a stage in something, or an aspect of something.","ex":{"en":"Where will it all end?","cn":"它会在哪儿全部结束？"}},{"pos":"CONJ-SUBORD 连词","cn":"(尤用于某些动词和形容词后，引导表示地点、某事物所处状态、阶段等的从句)在哪儿，从哪儿","en":"You use where after certain words, especially verbs and adjectives, to introduce a clause in which you mention a situation, a stage in something, or an aspect of something.","ex":{"en":"It's not hard to see where she got her feelings about herself","cn":"不难看出她从何处获得的这种自我感觉。"}},{"pos":"CONJ-SUBORD 连词","cn":"(用于引导从句进行对比)然而","en":"You use where to introduce a clause that contrasts with the other parts of the sentence.","ex":{"en":"Where some people learned to play the accordion for dances in their community, others took music lessons","cn":"一些人学习弹手风琴，为他们社区里的舞蹈表演进行伴奏，而其他人则上音乐课。"}}]},"examples":[{"en":"It's one of the few countries where people drive on the left.","cn":"这是为数不多的几个靠左行驶的国家之一。"},{"en":"We then moved to Paris, where we lived for six years.","cn":"我们随后移居巴黎，在那里住了六年。"}]},"wheel":{"oxford":{"phon":"wiːl","pos":"noun","senses":[{"en":"one of the round objects under a car, bicycle, bus, etc. that turns when it moves","cn":"轮；车轮；轮子","g":"[countable]","sc":"on/in vehicles","ex":{"en":"He braked suddenly, causing the front wheels to skid.","cn":"他猛然刹车，使得前车轮打滑了。"}},{"en":"the round object used for controlling the direction in which a car, etc. or ship moves","cn":"（汽车等的）方向盘；（轮船的）舵轮","g":"[countable, usually singular]","sc":"on/in vehicles","ex":{"en":"Always keep both hands on the wheel.","cn":"双手始终握住方向盘。"}},{"en":"a car","cn":"汽车","g":"[plural]","lab":"informal","sc":"on/in vehicles","ex":{"en":"At last he had his own wheels.","cn":"他终于有了自己的汽车。"}},{"en":"a flat, round part in a machine","cn":"机轮","g":"[countable]","sc":"in machine","ex":{"en":"gear wheels","cn":"齿轮"}},{"en":"an organization or a system that seems to work like a complicated machine that is difficult to understand","cn":"错综复杂的机构（或系统）","g":"[plural]","sc":"organization/system","ex":{"en":"the wheels of bureaucracy/commerce/government","cn":"复杂的官僚／商务／政府机构"}},{"en":"having the number or type of wheels mentioned","cn":"有…轮的","sc":"-wheeled","ex":{"en":"a sixteen-wheeled lorry","cn":"十六轮大卡车"}},{"en":"a car, bicycle, etc. with the number of wheels mentioned","cn":"有…轮子的汽车（或自行车等）","sc":"-wheeler","ex":{"en":"a three-wheeler","cn":"三轮机动车"}},{"en":"to push or pull something that has wheels","cn":"推（或拉）有轮之物","g":"[transitive]","sc":"move something/somebody with wheels","ex":{"en":"She wheeled her bicycle across the road.","cn":"她推着自行车穿过了马路。"},"pos":"verb"},{"en":"to move somebody/something that is in or on something that has wheels","cn":"用有轮之物推动（或拉动、移动）…","g":"[transitive]","sc":"move something/somebody with wheels","ex":{"en":"The nurse wheeled him along the corridor.","cn":"护士推着他沿楼道走。"},"pos":"verb"},{"en":"to move or fly in a circle","cn":"转动；旋转；打转；盘旋","g":"[intransitive]","sc":"move in circle","ex":{"en":"Birds wheeled above us in the sky.","cn":"鸟儿在我们上空盘旋。"},"pos":"verb"},{"en":"to turn quickly or suddenly and face the opposite direction; to make somebody/something do this","cn":"（使）迅速转身，猛然转身","g":"[intransitive, transitive]","sc":"turn quickly","ex":{"en":"She wheeled around and started running.","cn":"她突然转身就跑。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"轮;轮子;车轮","en":"The wheels of a vehicle are the circular objects which are fixed underneath it and which enable it to move along the ground.","ex":{"en":"The car wheels spun and slipped on some oil on the road.","cn":"路面上有些油，汽车车轮经过时直打滑。"}},{"pos":"N-COUNT 可数名词","cn":"机轮","en":"A wheel is a circular object which forms a part of a machine, usually a moving part.","ex":{"en":"...an eighteenth century mill with a water wheel.","cn":"一个带有水轮的18世纪磨粉机"}},{"pos":"N-COUNT 可数名词","cn":"方向盘","en":"The wheel of a car or other vehicle is the circular object that is used to steer it. The wheel is used in expressions to talk about who is driving a vehicle. For example, if someone is at the wheel of a car, they are driving it.","ex":{"en":"My co-pilot suddenly grabbed the wheel","cn":"我的副驾驶突然抓住了方向盘。"}},{"pos":"N-PLURAL 复数名词","cn":"汽车","en":"People sometimes refer to a car as wheels .","ex":{"en":"'Do you own a house?' — 'No. But I have wheels.'","cn":"“你有房吗？”——“没有，但我有车。”"}},{"pos":"VERB 动词","cn":"推(带轮子的物体)","en":"If you wheel an object that has wheels somewhere, you push it along.","ex":{"en":"He wheeled his bike into the alley at the side of the house","cn":"他把自行车推进了房子旁的小巷中。"}},{"pos":"VERB 动词","cn":"(动物、鸟禽等)转圈，旋转，盘旋","en":"If something such as a group of animals or birds wheels, it moves in a circle.","ex":{"en":"A flock of crows wheeled overhead.","cn":"一群乌鸦在头顶上盘旋。"}},{"pos":"VERB 动词","cn":"(因惊讶、震惊或生气)突然转身","en":"If you wheel around, you turn around suddenly where you are standing, often because you are surprised, shocked, or angry.","ex":{"en":"He wheeled around to face her","cn":"他突然转过身来面对她。"}},{"pos":"N-SING 单数名词","cn":"(尤指多次发生相同的情形)命运之轮","en":"You use wheel in expressions such as the wheel of fortune to refer to the changes that take place in life, especially when you are referring to the fact that the same situations occur more than once.","ex":{"en":"The wheel of fortune will swing round again; in politics, it always does","cn":"风水会轮流转；在政治上，它总是如此。"}},{"pos":"N-PLURAL 复数名词","cn":"(组织或系统的)运作方式","en":"People talk about the wheels of an organization or system to mean the way in which it operates. to oil the wheels→see: ;","ex":{"en":"He knows the wheels of administration turn slowly.","cn":"他知道行政机关办事效率低。"}},{"pos":"PHRASE 短语","cn":"(各种影响、原因和行动交织在一起的)错综复杂的情况","en":"If you say that there are wheels within wheels, you mean that there are a number of different influences, reasons, and actions which together make a situation complicated and difficult to understand.","ex":{"en":"Our culture is more complex than he knows. Wheels within wheels.","cn":"我们的文化比他所知道的要复杂得多，相当庞杂。"}}]},"media":{"uk":"media/uk/wheel__gb_1.mp3","us":"media/us/wheel__us_1.mp3"},"examples":[{"en":"There are wheels within wheels in this organization — you never really know what is going on.","cn":"这个机构里错综复杂，你永远搞不清到底是怎么回事。"},{"en":"One of the boys was pushing the other along in a little box on wheels.","cn":"一个男孩用下面装着轮子的小箱子推着另一个男孩。"}]},"whoa":{"media":{"uk":"media/uk/whoa__gb_1.mp3","us":"media/us/whoa__us_1.mp3"},"oxford":{"phon":"wəʊ","pos":"exclamation","senses":[{"en":"used as a command to a horse, etc. to make it go slower, stop or stand still","cn":"（吆喝马等停下或不动的口令）吁"}]},"collins":{"senses":[{"pos":"EXCLAM 感叹语","cn":"吁(用以吆喝马慢下来或停下来）","en":"Whoa is a command that you give to a horse to slow down or stop."},{"pos":"EXCLAM 感叹语","cn":"慢点，停（暗示说话人语速太快或内容不真实）","en":"You can say whoa to someone who is talking to you, to indicate that you think they are talking too fast or assuming things that may not be true.","ex":{"en":"Slow down! Whoa!","cn":"慢点！停！"}}]},"examples":[{"en":"Whoa! You’re driving too fast.","cn":"慢点！你开得太快了。"},{"en":"Whoa. That’s a lot of money.","cn":"哇﹐那可是一大笔钱。"}]},"white":{"media":{"uk":"media/uk/white__gb_1.mp3","us":"media/us/white__us_1.mp3","img":["media/ldoce/img/egg_cup.jpg"]},"oxford":{"phon":"waɪt","pos":"adjective","senses":[{"en":"having the colour of fresh snow or of milk","cn":"白的；白色的","ex":{"en":"a crisp white shirt","cn":"一件洁净挺括的白衬衫"}},{"en":"belonging to or connected with a group of people who have pale skin, especially people who come from or whose ancestors came from Europe","cn":"白人的","ex":{"en":"white middle-class families","cn":"白人中产阶级家庭"}},{"en":"pale because of emotion or illness","cn":"脸色苍白的","ex":{"en":"white with shock","cn":"震惊得脸色发白"}},{"en":"with milk added","cn":"加牛奶的","lab":"British English","ex":{"en":"Two white coffees, please.","cn":"请来两杯加牛奶的咖啡。"}},{"en":"the colour of fresh snow or of milk","cn":"白色；雪白；乳白","g":"[uncountable]","ex":{"en":"various shades of white","cn":"各种亮度的白"},"pos":"noun"},{"en":"a member of a group of people who have pale skin, especially people who come from or whose ancestors came from Europe","cn":"白人","g":"[countable, usually plural]","pos":"noun"},{"en":"white wine","cn":"白葡萄酒","g":"[uncountable, countable]","ex":{"en":"Would you like red or white?","cn":"你喜欢喝红葡萄酒还是白葡萄酒？"},"pos":"noun"},{"en":"the part of an egg that surrounds the yolk (= the yellow part)","cn":"蛋白；蛋清","g":"[countable, uncountable]","ex":{"en":"Use the whites of two eggs.","cn":"用两个鸡蛋的蛋清。"},"pos":"noun"},{"en":"the white part of the eye","cn":"眼白；白眼珠","g":"[countable, usually plural]","ex":{"en":"The whites of her eyes were bloodshot.","cn":"她的白眼珠布满血丝。"},"pos":"noun"},{"en":"white clothes, sheets, etc. when they are separated from coloured ones to be washed","cn":"要洗涤的白色衣服（或床单等）","g":"[plural]","lab":"British English","ex":{"en":"Don't wash whites and coloureds together.","cn":"别把白色衣服和带颜色的衣服一起洗。"},"pos":"noun"},{"en":"white clothes worn for playing some sports","cn":"白色运动服","g":"[plural]","ex":{"en":"cricket/tennis whites","cn":"白色板球／网球运动服"},"pos":"noun"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"白色;白","en":"Something that is white is the colour of snow or milk.","ex":{"en":"He had nice square white teeth","cn":"他的牙齿洁白而整齐，十分好看。"}},{"pos":"ADJ 形容词","cn":"白种人的;白肤色的","en":"A white person has a pale skin and belongs to a race which is of European origin.","ex":{"en":"Working with white people hasn't been a problem for me or for them","cn":"和白人共事对我、对他们来说都不是个问题。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(因情绪变化或生病等)脸色苍白的","en":"If someone goes white, the skin on their face becomes very pale, for example because of fear, shock, anger, or illness.","ex":{"en":"Richard had gone very white, but he stood his ground","cn":"理查德脸都白了，但还是坚持自己的立场。"}},{"pos":"ADJ 形容词","cn":"(葡萄酒)白的，淡黄色的","en":"White wine is pale yellow in colour.","ex":{"en":"Gregory poured another glass of white wine and went back to his bedroom.","cn":"格雷戈里又倒了一杯白葡萄酒后回到了卧室。"}},{"pos":"ADJ 形容词","cn":"(咖啡)加牛奶(或奶油)的","en":"White coffee has had milk or cream added to it.","ex":{"en":"Wayne has a large white coffee in front of him.","cn":"韦恩面前摆着一大杯加了牛奶的咖啡。"}},{"pos":"ADJ 形容词","cn":"(血细胞)白的","en":"White blood cells are the cells in your blood which your body uses to fight infection."},{"pos":"ADJ 形容词","cn":"(魔法)善意的","en":"People who believe in white magic believe it is possible to use magic to do good things.","ex":{"en":"...practitioners of white magic","cn":"施善意法术的人"}},{"pos":"N-VAR 可变名词","cn":"蛋白;蛋清","en":"The white of an egg is the transparent liquid that surrounds the yellow part called the yolk."},{"pos":"N-COUNT 可数名词","cn":"眼白","en":"The white of someone's eye is the white part that surrounds the coloured part called the iris."},{"pos":"N-PLURAL 复数名词","cn":"白色的运动服","en":"Whites are white clothes that you wear for playing some sports, for example tennis or cricket.","ex":{"en":"There was a Frenchman sitting at the next table, immaculate in tennis whites.","cn":"邻桌坐着位法国人，穿着非常整洁的白色网球服。"}}]},"examples":[{"en":"She writes about her experiences as a black girl in a predominantly white city.","cn":"她写的是自己身为一个黑人姑娘在以白人为主的城市里的经历。"},{"en":"( BrE ) Don't wash whites and coloureds together.","cn":"别把白色衣服和带颜色的衣服一块洗。"}]},"why":{"media":{"uk":"media/uk/why__gb_1.mp3","us":"media/us/why__us_1.mp3"},"oxford":{"phon":"waɪ","pos":"adverb","senses":[{"en":"used in questions to ask the reason for or purpose of something","cn":"（用于问句）为什么，为何","lab":"informal","ex":{"en":"Why were you late?","cn":"你为什么迟到？"}},{"en":"used in questions to suggest that it is not necessary to do something","cn":"（反问，表示不必）何必","ex":{"en":"Why get upset just because you got one bad grade?","cn":"何必因为一次成绩不好就想不开呢？"}},{"en":"used to give or talk about a reason","cn":"（说明理由）为什么，…的原因","ex":{"en":"That's why I left so early.","cn":"这就是我早早离去的原因。"}},{"en":"used to express a feeling of being surprised, impatient, etc.","cn":"（表示惊讶、不耐烦等）哎呀，呦，哟，嗨","ex":{"en":"Why Jane, it's you!","cn":"呦，简，是你呀！"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"QUEST 疑问词","cn":"（用于提问原因）为什么","en":"You use why in questions when you ask about the reasons for something.","ex":{"en":"Why hasn't he brought the whisky?","cn":"他为什么没把威士忌拿来？"}},{"pos":"CONJ-SUBORD 连词","cn":"(用于从句句首)为什么","en":"You use why at the beginning of a clause in which you talk about the reasons for something.","ex":{"en":"He still could not throw any further light on why the elevator could have become jammed","cn":"对于电梯为什么会卡住他仍旧给不出更多的解释。"}},{"pos":"PRON-REL 关系代词","cn":"(用于reason后引导关系从句)","en":"You use why to introduce a relative clause after the word 'reason'.","ex":{"en":"There's a reason why women don't read this stuff; it's not funny","cn":"女人不读这种东西是有原因的，它并不好笑。"}},{"pos":"QUEST 疑问词","cn":"(问句中与 not 连用表示建议)为什么(不)","en":"You use why with 'not' in questions in order to introduce a suggestion.","ex":{"en":"Why not give Claire a call?","cn":"为什么不给克莱尔打个电话？"}},{"pos":"QUEST 疑问词","cn":"(问句中与 not 连用表示恼怒或气愤)为什么(不)","en":"You use why with 'not' in questions in order to express your annoyance or anger.","ex":{"en":"Why don't you look where you're going?","cn":"走路怎么不看着点儿道呢？"}},{"pos":"CONVENTION 惯用语","cn":"(表示同意别人的建议)为什么不呢，好，行","en":"You say why not in order to agree with what someone has suggested.","ex":{"en":"'Want to spend the afternoon with me?' — 'Why not?'","cn":"“想和我共度这个下午吗？”——“好啊！”"}},{"pos":"EXCLAM 感叹语","cn":"(用于句首表示惊讶、震惊或生气)哎呀，哟，嗨","en":"People say 'Why!' at the beginning of a sentence when they are surprised, shocked, or angry.","ex":{"en":"Why hello, Tom","cn":"哎呀，你好，汤姆。"}},{"pos":"","cn":"","en":"the whys and wherefores→see: ;"}]},"examples":[{"en":"The reason why the injection needs repeating every year is that the virus changes.","cn":"每年需要重新注射的原因是这病毒经常变化。"},{"en":"Why bother to write? We'll see him tomorrow.","cn":"还费事写信干什么？我们明天就见到他了。"}]},"wheels":{"lemma":"wheel"},"whose":{"media":{"uk":"media/uk/whose__gb_1.mp3","us":"media/us/whose__us_1.mp3"},"oxford":{"phon":"huːz","pos":"determiner, pronoun","senses":[{"en":"used in questions to ask who something belongs to","cn":"（用于问句）谁的","ex":{"en":"Whose house is that?","cn":"那是谁的房子？"}},{"en":"used to say which person or thing you mean","cn":"（特指）那个人的，那一个的，其","ex":{"en":"He's a man whose opinion I respect.","cn":"他是我尊重其意见的人。"}},{"en":"used to give more information about a person or thing","cn":"（进一步提供信息时用）","ex":{"en":"Isobel, whose brother he was, had heard the joke before.","cn":"伊索贝尔，就是他的弟弟，以前曾经听说过这个笑话。"}}]},"collins":{"senses":[{"pos":"PRON-REL 关系代词","cn":"(用于关系从句的句首，表示与前句所提到的人或事物有所属关系或相关联）","en":"You use whose at the beginning of a relative clause where you mention something that belongs to or is associated with the person or thing mentioned in the previous clause.","ex":{"en":"I saw a man shouting at a driver whose car was blocking the street.","cn":"我看见一个男人正朝一个司机叫嚷，他的车把街道堵塞了。"}},{"pos":"QUEST 疑问词","cn":"(用于疑问句中，询问某物所属或其与何人何事有关)谁的","en":"You use whose in questions to ask about the person or thing that something belongs to or is associated with.","ex":{"en":"Whose was the better performance?","cn":"谁表演得更好?"}},{"pos":"DET-POSS 所有格限定词","cn":"(尤用在动词或形容词等后面，引导谈论某物所属或与何人何事相关的从句)谁的","en":"You use whose after certain words, especially verbs and adjectives, to introduce a clause where you talk about the person or thing that something belongs to or is associated with.","ex":{"en":"I'm wondering whose mother she is then","cn":"我很纳闷，那么她是谁的母亲呢？"}}]},"examples":[{"en":"Isobel, whose brother he was, had heard the joke before.","cn":"伊泽贝尔，就是他的弟弟，以前曾经听说过这个笑话。"},{"en":"It's the house whose door is painted red.","cn":"这就是那所门户涂成红色的房子。"}]},"whereas":{"oxford":{"phon":"ˌweərˈæz","pos":"conjunction","senses":[{"en":"used to compare or contrast two facts","cn":"（用以比较或对比两个事实）然而，但是，尽管","ex":{"en":"Some of the studies show positive results, whereas others do not.","cn":"有一些研究结果令人满意，然而其他的则不然。"}},{"en":"used at the beginning of a sentence in an official document to mean ‘because of the fact that…’","cn":"（用于正式文件中句子的开头）鉴于","lab":"law"}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"(表示对比)但是，然而","en":"You use whereas to introduce a comment which contrasts with what is said in the main clause.","ex":{"en":"Pensions are linked to inflation, whereas they should be linked to the cost of living","cn":"养老金与通货膨胀挂钩，然而它们其实应该和生活费用挂钩。"}}]},"media":{"uk":"media/uk/whereas__gb_1.mp3","us":"media/us/whereas__us_1.mp3"},"examples":[{"en":"Some of the studies show positive results, whereas others do not.","cn":"有一些研究结果令人满意，然而其他的则不然。"},{"en":"The old system was fairly complicated whereas the new system is really very simple.","cn":"旧系统相当复杂﹐而新系统却很简单。"}]},"whale":{"media":{"uk":"media/uk/whale__gb_1.mp3","us":"media/us/whale__us_1.mp3"},"oxford":{"phon":"weɪl","pos":"noun","senses":[{"en":"a very large animal that lives in the sea and looks like a very large fish. There are several types of whale, some of which are hunted.","cn":"鲸","ex":{"en":"whale meat","cn":"鲸肉"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鲸","en":"Whales are very large mammals that live in the sea. →see: ; →see: ; →see: ;"},{"pos":"PHRASE 短语","cn":"非常高兴;非常愉快","en":"If you say that someone is having a whale of a time, you mean that they are enjoying themselves very much.","ex":{"en":"I had a whale of a time in Birmingham.","cn":"我在伯明翰度过了一段非常快乐的时光。"}}]},"examples":[{"en":"whale meat","cn":"鲸肉"}]},"whenever":{"media":{"uk":"media/uk/whenever__gb_1.mp3","us":"media/us/whenever__us_1.mp3"},"oxford":{"phon":"wenˈevə(r)","pos":"conjunction","senses":[{"en":"at any time that; on any occasion that","cn":"在任何…的时候；无论何时；在任何…的情况下","ex":{"en":"You can ask for help whenever you need it.","cn":"你如果需要帮助随时可以提出来。"}},{"en":"every time that","cn":"每当；每次","ex":{"en":"Whenever she comes, she brings a friend.","cn":"她每次来都带着个朋友。"}},{"en":"used when the time when something happens is not important","cn":"别的什么时候（也可以）；任何时间（都行）","ex":{"en":"‘When do you need it by?’ ‘Saturday or Sunday. Whenever.’","cn":"“你什么时候需要这个东西？”“星期六或星期日。哪一天都行。”"}},{"en":"used in questions to mean ‘when’, expressing surprise","cn":"（用于问句，表示惊奇）究竟什么时候","ex":{"en":"Whenever did you find time to do all that cooking?","cn":"你怎么有时间做了这么多菜？"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"无论什么时候;每当","en":"You use whenever to refer to any time or every time that something happens or is true.","ex":{"en":"She always called at the vicarage whenever she was in the area","cn":"只要她在那一带，她总会去拜访教区牧师。"}},{"pos":"CONJ-SUBORD 连词","cn":"不知什么时候","en":"You use whenever to refer to a time that you do not know or are not sure about.","ex":{"en":"He married Miss Vancouver in 1963, or whenever it was.","cn":"他好像在1963年还是什么时候娶了当时的温哥华小姐。"}}]},"examples":[{"en":"‘When do you need it by?’ ‘Saturday or Sunday. Whenever.’ “","cn":"你什么时候需要这个东西？” “星期六或星期日。哪一天都行。”"},{"en":"It's not urgent — we can do it next week or whenever.","cn":"这不着急，我们可以在下星期或别的什么时候做。"}]},"whig":{"media":{"uk":"media/uk/whig__gb_1.mp3","us":"media/us/whig__us_1.mp3"},"oxford":{"phon":"wɪɡ","pos":"noun","senses":[{"en":"in Britain in the past, a member of a party that supported progress and change and that later became the Liberal Party","cn":"辉格党党员（属于英国旧时的激进党派，自由党的前身）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(18和19世纪致力于政治和社会改革的)辉格党成员","en":"A Whig was a member of a British political party in the 18th and 19th centuries that was in favour of political and social changes."},{"pos":"N-COUNT 可数名词","cn":"（美国）独立战争的支持者","en":"In the American Revolution, a Whig was an American who supported the revolution against the British."},{"pos":"N-COUNT 可数名词","cn":"(美国19世纪的想要限制总统权力的)政党成员","en":"A Whig was a member of an American political party in the 19th century that wanted to limit the powers of the President."}]}},"white-collar":{"oxford":{"phon":"ˌwaɪt ˈkɒlə(r)","pos":"adjective","senses":[{"en":"working in an office, rather than in a factory, etc.; connected with work in offices","cn":"白领的；文职的；脑力劳动的","ex":{"en":"white-collar workers","cn":"白领工作者"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"白领的;文职的;脑力劳动的","en":"White-collar workers work in offices rather than doing physical work such as making things in factories or building things.","ex":{"en":"White-collar workers now work longer hours.","cn":"如今白领工人的工作时间比以前更长了。"}},{"pos":"ADJ 形容词","cn":"(犯罪)白领的(指非法窃取公司、政府钱财等)","en":"White-collar crime is committed by people who work in offices, and involves stealing money secretly from companies or the government, or getting money in an illegal way."}]},"media":{"uk":"media/uk/white_collar_1_gb_1.mp3","us":"media/us/white_collar_1_us_1.mp3"},"examples":[{"en":"white-collar crime (= in which office workers steal from their company, etc.)","cn":"白领犯罪"},{"en":"white-collar workers","cn":"白领工作者"}]},"when":{"media":{"uk":"media/uk/when__gb_1.mp3","us":"media/us/when__us_1.mp3"},"oxford":{"phon":"wen","pos":"adverb","senses":[{"en":"at what time; on what occasion","cn":"什么时候；何时；什么情况下；什么场合下","ex":{"en":"When did you last see him?","cn":"你上次什么时候见到他的？"}},{"en":"used after an expression of time to mean ‘at which’ or ‘on which’","cn":"（用于时间的表达方式之后）在那时，其时","ex":{"en":"Sunday is the only day when I can relax.","cn":"星期日是我唯一可以休息的日子。"}},{"en":"at which time; on which occasion","cn":"其时；当时；当场","ex":{"en":"The last time I went to Scotland was in May, when the weather was beautiful.","cn":"我上次去苏格兰是在五月份，那时的天气好极了。"}},{"en":"what/which time","cn":"什么时候；何时","ex":{"en":"Until when can you stay?","cn":"你可以待到什么时候？"},"pos":"pronoun"},{"en":"at or during the time that","cn":"在…时候；当…时；在…期间","ex":{"en":"I loved history when I was at school.","cn":"我上学时喜欢历史。"},"pos":"conjunction"},{"en":"after","cn":"在…之后","ex":{"en":"Call me when you've finished.","cn":"你完成后就打电话给我。"},"pos":"conjunction"},{"en":"at any time that; whenever","cn":"在任何…时候","ex":{"en":"Can you spare five minutes when it's convenient?","cn":"方便时能占用你五分钟时间吗？"},"pos":"conjunction"},{"en":"just after which","cn":"一…就；刚…就","ex":{"en":"He had just drifted off to sleep when the phone rang.","cn":"他刚睡着电话铃就响了。"},"pos":"conjunction"},{"en":"considering that","cn":"考虑到；既然","ex":{"en":"How can they expect to learn anything when they never listen?","cn":"既然他们从不听讲，他们怎么能指望学到东西呢？"},"pos":"conjunction"},{"en":"although","cn":"虽然；然而；可是","ex":{"en":"She claimed to be 18, when I know she's only 16.","cn":"她自称是 18 岁，可是我知道她才 16 岁。"},"pos":"conjunction"}]},"collins":{"senses":[{"pos":"QUEST 疑问词","cn":"(用于疑问句)什么时候，何时","en":"You use when to ask questions about the time at which things happen.","ex":{"en":"When are you going home?","cn":"你什么时候回家？"}},{"pos":"CONJ-SUBORD 连词","cn":"(表示两事同时发生)在…时，当…时","en":"If something happens when something else is happening, the two things are happening at the same time.","ex":{"en":"When eating a whole cooked fish, you should never turn it over to get at the flesh on the other side","cn":"吃一整条鱼时，切忌把它翻过来去吃另一面的肉。"}},{"pos":"CONJ-SUBORD 连词","cn":"(引导从句，表示某事发生于另一活动、事件或情形期间)在…的过程中","en":"You use when to introduce a clause in which you mention something which happens at some point during an activity, event, or situation.","ex":{"en":"When I met the Gills, I had been gardening for nearly ten years.","cn":"遇到吉尔一家时我已经做了近10年的园艺工作。"}},{"pos":"CONJ-SUBORD 连词","cn":"(引导从句，说明主句动作已经发生或将要发生时的情况)其时","en":"You use when to introduce a clause where you mention the circumstances under which the event in the main clause happened or will happen.","ex":{"en":"When he brought Imelda her drink she gave him a genuine, sweet smile of thanks","cn":"当他把饮料拿给艾梅尔达时，她真诚而甜美地向他微笑以示感谢。"}},{"pos":"CONJ-SUBORD 连词","cn":"(尤用于动词和形容词后引导从句，表示某事发生的时间)什么时候,何时","en":"You use when after certain words, especially verbs and adjectives, to introduce a clause where you mention the time at which something happens.","ex":{"en":"I asked him when he'd be back to pick me up","cn":"我问他什么时候回来接我。"}},{"pos":"PRON-REL 关系代词","cn":"(用于引导从句，限定或指示某事发生的时间)…的时候","en":"You use when to introduce a clause which specifies or refers to the time at which something happens.","ex":{"en":"He could remember a time when he had worked like that himself","cn":"他还能记得自己一度工作起来也是那个样子。"}},{"pos":"CONJ-SUBORD 连词","cn":"(用于引出某个观点、评论或问题的原因)既然，考虑到","en":"You use when to introduce the reason for an opinion, comment, or question.","ex":{"en":"How can I love myself when I look like this?","cn":"我这个样子，怎么能对自己满意呢？"}},{"pos":"CONJ-SUBORD 连词","cn":"(用于引出使句子的其他部分显得让人吃惊或不大可能的事实或评论)虽然，然而,可是","en":"You use when in order to introduce a fact or comment which makes the other part of the sentence rather surprising or unlikely.","ex":{"en":"Our mothers sat us down to read and paint, when all we really wanted to do was to make a mess","cn":"我们的母亲让我们坐下来读书和画画，而我们真正想做的却是打打闹闹。"}}]},"examples":[{"en":"She claimed to be 18, when I know she's only 16.","cn":"她自称是 18 岁，可是我知道她才 16 岁。"},{"en":"The last time I went to Scotland was in May, when the weather was beautiful.","cn":"我上次去苏格兰是在五月份，那时的天气好极了。"}]},"while":{"media":{"uk":"media/uk/while__gb_1.mp3","us":"media/us/while__us_1.mp3"},"oxford":{"phon":"waɪl","pos":"conjunction","senses":[{"en":"during the time that something is happening; at the same time as something else is happening","cn":"在…期间；当…的时候；与…同时","ex":{"en":"We must have been burgled while we were asleep.","cn":"我们肯定是在睡着时遭遇了入室盗窃。"}},{"en":"used to contrast two things","cn":"（对比两件事物）…而，…然而","ex":{"en":"While Tom's very good at science, his brother is absolutely hopeless.","cn":"汤姆很擅长理科，而他的弟弟绝对是不可救药。"}},{"en":"although; despite the fact that…","cn":"虽然；尽管","ex":{"en":"While I am willing to help, I do not have much time available.","cn":"尽管我愿意帮忙，但是没有多少时间。"}},{"en":"a period of time","cn":"一段时间；一会儿","ex":{"en":"I only stayed for a short while.","cn":"我只待了一小会儿。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"(表示两件事同时发生)当…的时候，在…时","en":"If something happens while something else is happening, the two things are happening at the same time.","ex":{"en":"They were grinning and watching while one man laughed and poured beer over the head of another","cn":"当一个男人大笑着把啤酒倒在另一个人头上时，他们都在乐呵呵地看着。"}},{"pos":"CONJ-SUBORD 连词","cn":"(表示某一件事是在另一件事发生过程中的某一时间点发生的)当…的时候，在…时","en":"If something happens while something else happens, the first thing happens at some point during the time that the second thing is happening.","ex":{"en":"The two ministers have yet to meet, but may do so while in New York","cn":"两位部长尚未会面，但可能会在纽约碰头。"}},{"pos":"CONJ-SUBORD 连词","cn":"却;但是;然而","en":"You use while at the beginning of a clause to introduce information which contrasts with information in the main clause.","ex":{"en":"Marianne was tempted to turn the large rooms into traditional French-style salons, while Howard was in favour of a typically English look","cn":"玛丽安娜想把这些大房间弄成传统法式客厅的样子，但是霍华德喜欢典型的英式风格。"}},{"pos":"CONJ-SUBORD 连词","cn":"虽然;尽管","en":"You use while, before making a statement, in order to introduce information that partly conflicts with your statement.","ex":{"en":"While the numbers of such developments are relatively small, the potential market is large","cn":"尽管这种增长的数量相对较小，但是潜在的市场是巨大的。"}},{"pos":"N-SING 单数名词","cn":"一段时间;一会儿","en":"A while is a period of time.","ex":{"en":"They walked on in silence for a while","cn":"他们默默地走了一会儿。"}},{"pos":"PHRASE 短语","cn":"不断;一直;始终","en":"You use all the while in order to say that something happens continually or that it happens throughout the time when something else is happening.","ex":{"en":"All the while the people at the next table watched me eat.","cn":"我吃东西的时候邻桌的人一直在看我。"}},{"pos":"","cn":"","en":"once in a while→see: ; worth your while→see: ;"},{"pos":"","cn":"","en":"相关词组：while away"}]},"examples":[{"en":"‘I'm just going to buy some postcards.’ ‘Can you get me some stamps while you're at it?’ “","cn":"我正想去买明信片。” “你能顺便给我买些邮票吗？”"},{"en":"While I was waiting at the bus stop, three buses went by in the opposite direction.","cn":"我在公共汽车站等车时，对向驶过了三辆公共汽车。"}]},"which":{"media":{"uk":"media/uk/which__gb_1.mp3","us":"media/us/which__us_1.mp3"},"oxford":{"phon":"wɪtʃ","pos":"pronoun, determiner","senses":[{"en":"used in questions to ask somebody to be exact about one or more people or things from a limited number","cn":"哪一个；哪一些","ex":{"en":"Which is better exercise—swimming or tennis?","cn":"游泳和网球，哪种运动比较好？"}},{"en":"used to be exact about the thing or things that you mean","cn":"（明确所指的事物）…的那个，…的那些","ex":{"en":"Houses which overlook the lake cost more.","cn":"俯瞰湖泊的房子要价高些。"}},{"en":"used to give more information about something","cn":"（进一步提供有关某事物的信息）那个，那些","ex":{"en":"His best movie, which won several awards, was about the life of Gandhi.","cn":"他最优秀的电影，就是荣获几项大奖的那一部，是关于甘地生平的。"}},{"en":"a British organization that tests the quality of products and publishes the results each month in its magazine Which? and on its website. This helps people to choose the best products and also gives the organization influence, which it uses to protect the interests of people who buy goods or use services. The organization was formed in 1957 by the Consumers' Association.","cn":"哪个？：一家测试产品质量并每月在其杂志中发布结果的英国组织？并在其网站上。这有助于人们选择最好的产品，并赋予组织影响力，以保护购买商品或使用服务的人们的利益。该组织由消费者协会于1957年成立。","pos":""}]},"collins":{"senses":[{"pos":"QUEST 疑问词","cn":"(用于疑问句中)哪个，哪些","en":"You use which in questions when there are two or more possible answers or alternatives.","ex":{"en":"Which do they want me to do? declare war or surrender?","cn":"他们想让我做什么,宣战还是投降？"}},{"pos":"DET 限定词","cn":"(用于指明在两个或多个答案或选项中所作出的选择)哪个，哪些","en":"You use which to refer to a choice between two or more possible answers or alternatives.","ex":{"en":"I wanted to know which school it was you went to","cn":"我想知道你上的是哪所学校。"}},{"pos":"PRON-REL 关系代词","cn":"(用于关系从句句首，具体说明所谈论的事物或提供关于它的更多信息)","en":"You use which at the beginning of a relative clause when specifying the thing that you are talking about or when giving more information about it.","ex":{"en":"Soldiers opened fire on a car which failed to stop at an army checkpoint","cn":"士兵向那辆拒绝在军事检查站停车检查的汽车开了火。"}},{"pos":"PRON-REL 关系代词","cn":"(用来回指前面句子表达的观点或状况)这，那","en":"You use which to refer back to an idea or situation expressed in a previous sentence or sentences, especially when you want to give your opinion about it.","ex":{"en":"They ran out of drink. Which actually didn't bother me because I wasn't drinking","cn":"他们把酒喝完了。但实际上这对我来说无所谓，因为我不喝酒。"}},{"pos":"PHRASE 短语","cn":"哪个是哪个(用于表示无法区分)","en":"If you cannot tell the difference between two things, you can say that you do not know which is which .","ex":{"en":"They all look so alike to me that I'm never sure which is which","cn":"对我来说他们看起来全都非常相似，我永远搞不清哪个是哪个。"}},{"pos":"","cn":"","en":"any which way→see: ; every which way→see: ;"}]},"examples":[{"en":"His best movie, which won several awards, was about the life of Gandhi.","cn":"他最优秀的电影，就是荣获几项大奖的那一部，是关于甘地生平的。"},{"en":"Your claim ought to succeed, in which case the damages will be substantial.","cn":"你的索赔应当能成功，假如这样的话，损害赔偿金将会相当可观。"}]},"what":{"media":{"uk":"media/uk/what__gb_1.mp3","us":"media/us/what__us_1.mp3"},"oxford":{"phon":"wɒt","pos":"pronoun, determiner","senses":[{"en":"used in questions to ask for particular information about somebody/something","cn":"什么","ex":{"en":"What is your name?","cn":"你叫什么名字？"}},{"en":"the thing or things that; whatever","cn":"…的事物；无论什么；凡是…的事物","ex":{"en":"What you need is a good meal.","cn":"你需要的是一顿美餐。"}},{"en":"used to say that you think that something is especially good, bad, etc.","cn":"多么；真；太","ex":{"en":"What awful weather!","cn":"天气太糟糕了！"}}]},"collins":{"senses":[{"pos":"QUEST 疑问词","cn":"(用于疑问句中询问所不知道的信息)什么","en":"You use what in questions when you ask for specific information about something that you do not know.","ex":{"en":"What do you want?","cn":"你想要什么？"}},{"pos":"CONJ-SUBORD 连词","cn":"（尤用于动词和形容词后以引导关系从句）","en":"You use what after certain words, especially verbs and adjectives, when you are referring to a situation that is unknown or has not been specified.","ex":{"en":"You can imagine what it would be like driving a car into a brick wall at 30 miles an hour","cn":"你可以想象汽车以每小时30英里的速度撞向一堵砖墙结果会怎样。"}},{"pos":"CONJ-SUBORD 连词","cn":"(用在强调句型的句首)所…的(是…)","en":"You use what at the beginning of a clause in structures where you are changing the order of the information to give special emphasis to something.","ex":{"en":"What precisely triggered off yesterday's riot is still unclear","cn":"究竟是什么引发了昨天的骚乱还不清楚。"}},{"pos":"CONJ-SUBORD 连词","cn":"…那样的(事物)","en":"You use what in expressions such as what is called and what amounts to when you are giving a description of something.","ex":{"en":"She had been in what doctors described as an irreversible vegetative state for five years","cn":"她处于医生所说的不可逆性植物人状态已经5年了。"}},{"pos":"CONJ-SUBORD 连词","cn":"(用于指全部的量)所有的","en":"You use what to indicate that you are talking about the whole of an amount that is available to you.","ex":{"en":"He drinks what is left in his glass as if it were water","cn":"他把杯子里剩下的东西当水一样全喝了下去。"}},{"pos":"CONVENTION 惯用语","cn":"(表示已经听到对方的话，并请其继续说)什么事","en":"You say 'What?' to tell someone who has indicated that they want to speak to you that you have heard them and are inviting them to continue.","ex":{"en":"'Dad?' — 'What?' — 'Can I have the car tonight?'","cn":"“爸爸？”——“什么事？”——“我今晚能用车吗？”"}},{"pos":"CONVENTION 惯用语","cn":"(用于没有听清或听懂时，请求他人再重复一遍刚说的话;不如 pardon，excuse me 等正式和礼貌)什么","en":"You say 'What?' when you ask someone to repeat the thing that they have just said because you did not hear or understand it properly. 'What?' is more informal and less polite than expressions such as 'Pardon?' and 'Excuse me?'.","ex":{"en":"'They could paint this place,' she said. 'What?' he asked.","cn":"“他们可以粉刷这个地方，”她说。“什么？”他问。"}},{"pos":"CONVENTION 惯用语","cn":"(用于表示惊讶)什么，真的吗","en":"You say 'What' to express surprise.","ex":{"en":"'Adolphus Kelling, I arrest you on a charge of trafficking in narcotics.'—'What?'","cn":"“阿道弗斯·克林，我以贩毒的罪名逮捕你。”——“什么？”"}},{"pos":"PREDET 前置限定词","cn":"(用在感叹句中强调某种意见或反应)多么","en":"You use what in exclamations to emphasize an opinion or reaction.","ex":{"en":"What a horrible thing to do","cn":"做这样的事简直太可怕了！"}},{"pos":"ADV 副词","cn":"(用于猜测时)嗯，哦","en":"You use what to indicate that you are making a guess about something such as an amount or value.","ex":{"en":"It's, what, eleven years or more since he's seen him","cn":"打从他上次见他，已有，嗯，11年甚至更久了。"}},{"pos":"CONVENTION 惯用语","cn":"你猜怎么着，你知道吗(表示接下来的信息令人惊讶，很少有人知道或者需要强调 )","en":"You say guess what or do you know what to introduce a piece of information which is surprising, which is not generally known, or which you want to emphasize.","ex":{"en":"Guess what? I'm going to dinner at Mrs. Combley's tonight","cn":"你猜怎么着？今晚我要去康伯利夫人家里赴宴。"}},{"pos":"PHRASE 短语","cn":"(用于疑问句后，表示语气强烈地陈述观点，并希望他人赞同)难道不是吗，是不是啊","en":"In conversation, you say or what? after a question as a way of stating an opinion forcefully and showing that you expect other people to agree.","ex":{"en":"Look at that moon. Is that beautiful or what?","cn":"看看那月亮，它真漂亮，不是吗？"}},{"pos":"CONVENTION 惯用语","cn":"(用来暗指之前的话不重要、无趣或与己无关)那又怎样，那又如何","en":"You say so what? or what of it? to indicate that the previous remark seems unimportant, uninteresting, or irrelevant to you.","ex":{"en":"'I skipped off school today,' — 'So what? What's so special about that?'","cn":"“我今天逃学了。”——“那又怎样？有什么特别的吗？”"}},{"pos":"PHRASE 短语","cn":"(用于提出建议)我有个主意，你听我说","en":"You say 'Tell you what' to introduce a suggestion or offer.","ex":{"en":"Tell you what, let's stay here another day.","cn":"我想，我们可以在这里再呆一天。"}},{"pos":"PHRASE 短语","cn":"(用于问句句首，表示提出建议或请求)…怎么样","en":"You use what about at the beginning of a question when you make a suggestion, offer, or request.","ex":{"en":"What about going out with me tomorrow?","cn":"明天和我一起出去怎么样？"}},{"pos":"PHRASE 短语","cn":"(用于引出与之前内容相关的新的话题或观点)那么…怎么样","en":"You use what about or what of when you introduce a new topic or a point which seems relevant to a previous remark.","ex":{"en":"Now you've talked about work on daffodils, what about other commercially important flowers, like roses?","cn":"既然你们已谈到了种植水仙花，那么其他具有重要商业价值的花卉呢，比如玫瑰？"}},{"pos":"PHRASE 短语","cn":"(用于请某人解释原因)…怎么了","en":"You say what about a particular person or thing when you ask someone to explain why they have asked you about that person or thing.","ex":{"en":"'This thing with the Corbett woman.'—'Oh, yeah. What about her?'","cn":"“是跟那个科比特家的女人有关的事。”——“哦，是吗，她怎么了？”"}},{"pos":"PHRASE 短语","cn":"诸如此类;等等","en":"You say what have you at the end of a list in order to refer generally to other things of the same kind.","ex":{"en":"So many things are unsafe these days—milk, cranberry sauce, what have you","cn":"现如今很多食品都不安全——牛奶、蓝莓酱等等。"}},{"pos":"PHRASE 短语","cn":"(用于疑问句句首，尤用于询问不希望看到的事发生时的结果)如果…怎么办","en":"You say what if at the beginning of a question when you ask about the consequences of something happening, especially something undesirable.","ex":{"en":"What if this doesn't work out?","cn":"如果这个不行怎么办？"}},{"pos":"PHRASE 短语","cn":"重要的事情","en":"If you know what's what, you know the important things that need to be known about a situation.","ex":{"en":"You have to know what's what and when to draw the line","cn":"你必须搞清状况以及自己的底线。"}},{"pos":"PREP-PHRASE 短语介词","cn":"(尤指不想看到的情况的发生)由于，因为","en":"You say what with in order to introduce the reasons for a particular situation, especially an undesirable one.","ex":{"en":"Maybe they are tired, what with all the sleep they're losing staying up night after night","cn":"也许他们是太累了，考虑到他们成宿成宿地熬夜。"}},{"pos":"CONVENTION 惯用语","cn":"(表示不相信或不能接受某人刚说的话，或没有听清或完全理解)你说什么？","en":"People say 'you what?' to indicate that they do not believe or accept the remark that someone has just made, or that they have not heard or understood it properly.","ex":{"en":"'I'm going to have problems sleeping tonight.' — 'You what?'","cn":"“今晚我可能睡不着。”——“不会吧？”"}},{"pos":"","cn":"","en":"what's more→see: ;"}]},"examples":[{"en":"What with the cold weather and my bad leg, I haven't been out for weeks.","cn":"由于天气很冷，我的腿又不好，我已经好几个星期没有出门了。"},{"en":"What's with all this walking? Can't we take a cab?","cn":"怎么就这么一直走？难道我们就不能打辆出租车吗？"}]},"wholesale":{"media":{"uk":"media/uk/wholesale__gb_1.mp3","us":"media/us/wholesale__us_1.mp3"},"oxford":{"phon":"ˈhəʊlseɪl","pos":"adverb","senses":[{"en":"in large quantities, especially so they can be sold again to make a profit","cn":"批发的；趸售的","ex":{"en":"We buy the building materials wholesale.","cn":"我们批量购买建筑材料。"}},{"en":"in very large numbers","cn":"大规模的","ex":{"en":"These young people die wholesale from heroin overdoses.","cn":"这些年轻人因过量吸食海洛因大批死亡。"}},{"en":"connected with goods that are bought and sold in large quantities, especially so they can be sold again to make a profit","cn":"批发的；趸售的","ex":{"en":"wholesale prices","cn":"批发价格"},"pos":"adjective"},{"en":"happening or done to a very large number of people or things","cn":"大规模的","ex":{"en":"the wholesale slaughter of innocent people","cn":"对无辜民众的大屠杀"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"批发;趸售","en":"Wholesale is the activity of buying and selling goods in large quantities and therefore at cheaper prices, usually to shopkeepers who then sell them to the public.","ex":{"en":"Warehouse clubs allow members to buy goods at wholesale prices","cn":"仓储式会员店允许会员以批发价购买商品。"}},{"pos":"ADV 副词","cn":"用批发方式;以批发价","en":"If something is sold wholesale, it is sold in large quantities and at cheaper prices, usually to shopkeepers.","ex":{"en":"The fabrics are sold wholesale to retailers, fashion houses, and other manufacturers.","cn":"这些纺织品被批发给零售商、时装店和其他制造商。"}},{"pos":"ADJ 形容词","cn":"大规模的;大批的","en":"You use wholesale to describe the destruction, removal, or changing of something when it affects a very large number of things or people.","ex":{"en":"They are only doing what is necessary to prevent wholesale destruction of vegetation","cn":"他们只是在采取必要措施避免大规模的植被破坏。"}}]},"examples":[{"en":"These young people die wholesale from heroin overdoses.","cn":"这些年轻人因过量吸海洛因大批死亡。"},{"en":"We buy the building materials wholesale.","cn":"我们批量购买建筑材料。"}]},"whatever":{"media":{"uk":"media/uk/whatever__gb_1.mp3","us":"media/us/whatever__us_1.mp3"},"oxford":{"phon":"wɒtˈevə(r)","pos":"determiner, pronoun","senses":[{"en":"any or every; anything or everything","cn":"任何；每一；任何事物；一切事物","ex":{"en":"Take whatever action is needed.","cn":"采取任何必要的行动。"}},{"en":"used when you are saying that it does not matter what somebody does or what happens, because the result will be the same","cn":"（表示做什么或发生什么都没关系，因结果都一样）无论什么，不管什么","ex":{"en":"Whatever decision he made I would support it.","cn":"无论他作出什么决定我都会支持的。"}},{"en":"used in questions to express surprise or lack of understanding","cn":"（用于问句，表示惊讶或困惑）到底是什么，究竟是什么","lab":"especially British English","ex":{"en":"Whatever do you mean?","cn":"你究竟是什么意思？"}},{"en":"used as a reply to tell somebody that you do not care what happens or that you are not interested in what they are talking about","cn":"（用于回应，表示不在乎或不感兴趣）或许吧，无所谓","lab":"informal, ironic，，","ex":{"en":"‘You should try a herbal remedy.’ ‘Yeah, whatever.’","cn":"“你应该试一试草药疗法。”“是啊，或许吧。”"}},{"en":"used to say that you do not mind what you do, have, etc. and that anything is acceptable","cn":"（表示不在乎，什么都可接受）什么都可以","lab":"informal","ex":{"en":"‘What would you like to do today?’ ‘Whatever.’","cn":"“今天你想做什么呢？”“做什么都可以。”"}},{"en":"not at all; not of any kind","cn":"一点儿都（不）；丝毫（不）；什么都（没有）","ex":{"en":"They received no help whatever.","cn":"他们没有得到一点儿帮助。"},"pos":"adverb"},{"en":"used to say that it does not matter what somebody does, or what happens, because the result will be the same","cn":"不管发生什么","lab":"informal","ex":{"en":"We told him we'd back him whatever.","cn":"我们告诉他，在任何情况下我们都会支持他。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"任何…的事物;凡是…的东西","en":"You use whatever to refer to anything or everything of a particular type.","ex":{"en":"Franklin was free to do pretty much whatever he pleased","cn":"富兰克林几乎可以做自己喜欢做的任何事情。"}},{"pos":"CONJ-SUBORD 连词","cn":"不管什么；无论什么","en":"You use whatever to say that something is the case in all circumstances.","ex":{"en":"We shall love you whatever happens, Diana","cn":"戴安娜，不管发生什么，我们都爱你。"}},{"pos":"ADV 副词","cn":"(用于名词词组后，强调否定陈述)任何，丝毫","en":"You use whatever after a noun group in order to emphasize a negative statement.","ex":{"en":"There is no evidence whatever that competition in broadcasting has ever reduced costs","cn":"没有任何证据表明，广播业的竞争使成本有所降低。"}},{"pos":"QUEST 疑问词","cn":"(强调询问语气)究竟，到底","en":"You use whatever to ask in an emphatic way about something which you are very surprised about.","ex":{"en":"Whatever can you mean?","cn":"你到底是什么意思？"}},{"pos":"CONJ-SUBORD 连词","cn":"(用于表示不清楚刚才所提到事物的准确特征、含义、价值等)不管什么，随便怎样","en":"You use whatever when you are indicating that you do not know the precise identity, meaning, or value of the thing just mentioned.","ex":{"en":"I thought that my upbringing was 'normal', whatever that is","cn":"我认为我的成长过程甭管怎么说还算“正常”。"}},{"pos":"PHRASE 短语","cn":"诸如此类","en":"You say or whatever to refer generally to something else of the same kind as the thing or things that you have just mentioned.","ex":{"en":"You may like a Malt whisky that is peatier, or smokier, or sweeter, or whatever.","cn":"你可能想来一杯麦芽威士忌，炭香味重些的、烟熏味重些的或者更甘甜些的，或者什么别的口味的。"}},{"pos":"CONVENTION 惯用语","cn":"(表示勉强接受)随便你怎么说","en":"You say 'whatever you say' to indicate that you accept what someone has said, even though you do not really believe them or do not think it is a good idea.","ex":{"en":"'We'll go in your car, Billy.'—'Whatever you say.'","cn":"“比利，我们要坐你的车。”——“随便。”"}},{"pos":"PHRASE 短语","cn":"(用于提出建议或警告)不管做什么，无论怎样","en":"You say whatever you do when giving advice or warning someone about something.","ex":{"en":"Whatever you do, don't look for a pay increase when you know the company is going through some difficulty","cn":"不管怎样，在知道公司遭遇困境时不要指望加薪。"}}]},"examples":[{"en":"It's the same in any situation: in a prison, hospital or whatever.","cn":"这在什么场合都一样：在监狱、医院或诸如此类的地方。"},{"en":"‘You should try a herbal remedy.’ ‘Yeah, whatever.’ “","cn":"你应该试一试草药疗法。” “是啊，或许吧。”"}]},"whiskered":{"media":{"uk":"media/uk/whiskered__gb_1.mp3","us":"media/us/whiskered__us_1.mp3"},"oxford":{"phon":"ˈwɪskəd","pos":"adjective","senses":[{"en":"having whiskers","cn":"有络腮胡子的；有须的"}]}},"whom":{"media":{"uk":"media/uk/whom__gb_1.mp3","us":"media/us/whom__us_1.mp3"},"oxford":{"phon":"huːm","pos":"pronoun","senses":[{"en":"used instead of ‘who’ as the object of a verb or preposition","cn":"（代替 who，用作动词或介词的宾语）谁，什么人","ex":{"en":"Whom did they invite?","cn":"他们邀请谁了？"}}]},"collins":{"senses":[{"pos":"QUEST 疑问词","cn":"(用于疑问句，询问人的姓名或身份)谁","en":"You use whom in questions when you ask about the name or identity of a person or group of people.","ex":{"en":"'I want to send a telegram.' — 'Fine, to whom?'","cn":"“我想发份电报。”——“好的，发给谁？”"}},{"pos":"CONJ-SUBORD 连词","cn":"(尤用于某些动词和形容词后，引导谈论某人或某一群人的姓名或身份的从句)谁","en":"You use whom after certain words, especially verbs and adjectives, to introduce a clause where you talk about the name or identity of a person or a group of people.","ex":{"en":"He asked whom I'd told about his having been away","cn":"他问我把他曾离开的消息告诉过谁。"}},{"pos":"PRON-REL 关系代词","cn":"(用于进行限定说明或提供更多信息的关系从句的句首)","en":"You use whom at the beginning of a relative clause when specifying the person or group of people you are talking about or when giving more information about them. →see usage note at:","ex":{"en":"One writer in whom I had taken an interest was Immanuel Velikovsky","cn":"我感兴趣的其中一位作家是伊曼纽尔·韦利科夫斯基。"}}]},"examples":[{"en":"The author whom you criticized in your review has written a reply.","cn":"你在评论中批评的那位作者已经回信答复了。"},{"en":"Our doctor, who/whom we all liked very much, retired last week.","cn":"我们的医生上周退休了，我们都很爱戴他。"}]},"whereabouts":{"media":{"uk":"media/uk/whereabouts__gb_1.mp3","us":"media/us/whereabouts__us_1.mp3"},"oxford":{"phon":"ˈweərəbaʊts","pos":"noun","senses":[{"en":"the place where somebody/something is","cn":"（人或物）所在的地方；下落；行踪","ex":{"en":"His whereabouts are/is still unknown.","cn":"他仍下落不明。"}},{"en":"used to ask the general area where somebody/something is","cn":"（用以询问大概的地方）在什么地方，在哪里","ex":{"en":"Whereabouts did you find it?","cn":"你在哪儿找到它的？"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"N-SING-COLL 单数集合名词","cn":"(人或物的)行踪，下落，所在之处","en":"If you refer to the whereabouts of a particular person or thing, you mean the place where that person or thing may be found.","ex":{"en":"The police are anxious to hear from anyone who may know the whereabouts of the firearms","cn":"警方急盼任何可能知道这批武器下落的人提供线索。"}},{"pos":"QUEST 疑问词","cn":"(用于疑问句)具体在哪里","en":"You use whereabouts in questions when you are asking precisely where something is.","ex":{"en":"Whereabouts in Liverpool are you from?","cn":"你从利物浦什么地方来的？"}},{"pos":"CONJ-SUBORD 连词","cn":"(尤用于某些动词和形容词后，引导表示具体处所的从句)具体在哪里","en":"You use whereabouts after certain words, especially verbs and adjectives, to introduce a clause in which you mention precisely where something is situated or happens.","ex":{"en":"I live in a village near to Germaine Greer and know whereabouts she lives.","cn":"我住在杰曼·格里尔家附近的村子里，知道她具体住在哪儿。"}}]},"examples":[{"en":"Whereabouts did you find it?","cn":"你在哪儿找到它的？"},{"en":"His whereabouts are/is still unknown.","cn":"他仍下落不明。"}]},"whistled":{"lemma":"whistle"},"wherever":{"media":{"uk":"media/uk/wherever__gb_1.mp3","us":"media/us/wherever__us_1.mp3"},"oxford":{"phon":"weərˈevə(r)","pos":"conjunction","senses":[{"en":"in any place","cn":"在任何地方","ex":{"en":"Sit wherever you like.","cn":"你爱坐在哪儿就坐哪儿。"}},{"en":"in all places that","cn":"在…的各个地方；各处；处处","ex":{"en":"Wherever she goes, there are crowds of people waiting to see her.","cn":"她所到之处都有成群的人等着见她。"}},{"en":"in all cases that","cn":"在所有…的情况下","ex":{"en":"Use wholegrain breakfast cereals wherever possible.","cn":"只要有可能就用全谷物早餐食品。"}},{"en":"used in questions to mean ‘where’, expressing surprise","cn":"（用于问句，表示惊讶）究竟在哪里，究竟到哪儿","ex":{"en":"Wherever can he have gone to?","cn":"他究竟会到哪儿去了呢？"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"无论哪里;在任何地方","en":"You use wherever to indicate that something happens or is true in any place or situation.","ex":{"en":"Some people enjoy themselves wherever they are","cn":"有些人能够随遇而安。"}},{"pos":"CONJ-SUBORD 连词","cn":"不管在哪里","en":"You use wherever when you indicate that you do not know where a person or place is.","ex":{"en":"I'd like to leave as soon as possible and join my children, wherever they are","cn":"我想尽快离开，回到儿女们中间去，不管他们在哪儿。"}},{"pos":"QUEST 疑问词","cn":"(用在疑问句中作为where的强调形式，通常表示惊讶)究竟在哪里","en":"You use wherever in questions as an emphatic form of 'where', usually when you are surprised about something.","ex":{"en":"Wherever did you get that idea?","cn":"你到底从哪儿得来的那个主意？"}},{"pos":"PHRASE 短语","cn":"或别的什么地方","en":"You use or wherever to say that something might happen in a place other than the place you have mentioned, but that you are not able to say exactly where.","ex":{"en":"The next day she was gone to Lusaka, Kampala, or wherever.","cn":"第二天她去了卢萨卡，坎帕拉或别的什么地方。"}}]},"examples":[{"en":"tourists from Spain, France or wherever","cn":"来自西班牙、法国或任何别的地方的游客"},{"en":"He comes from Boula, wherever that may be (= I don't know where it is).","cn":"他的原籍是布拉，管它在什么地方呢。"}]},"whispered":{"lemma":"whisper"},"whatsoever":{"collins":{"senses":[{"pos":"ADV 副词","cn":"(用于名词词组后，强调否定陈述)丝毫，任何，无论什么","en":"You use whatsoever after a noun group in order to emphasize a negative statement.","ex":{"en":"My school did nothing whatsoever in the way of athletics","cn":"我的学校在体育方面无所作为。"}}]},"media":{"uk":"media/ldoce/hwd/bre/5/whatsoever0205.mp3","us":"media/ldoce/hwd/ame/3/laadwhatsoever.mp3"},"examples":[{"en":"He’s had no luck whatsoever.","cn":"他一点也不走运。"}],"oxford":{"phon":"ˌwɒtsəʊˈevə(r)","pos":"adverb","senses":[{"en":"not at all; not of any kind","cn":"一点儿都（不）；丝毫（不）；什么都（没有）","ex":{"en":"They received no help whatsoever.","cn":"他们没有得到任何帮助。"}}]}},"wheezing":{"lemma":"wheeze"},"what's":{"collins":{"senses":[{"pos":"","cn":"(尤当 has 为助动词时，what is 或 what has 的常用口语形式)","en":"What's is the usual spoken form of 'what is' or 'what has', especially when 'has' is an auxiliary verb."}]}},"whatnots":{"lemma":"whatnot"},"whim":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"一时的兴致;心血来潮;突发的奇想","en":"A whim is a wish to do or have something which seems to have no serious reason or purpose behind it, and often occurs suddenly.","ex":{"en":"We decided, more or less on a whim, to sail to Morocco","cn":"我们多少有点心血来潮，决定航海去摩洛哥。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden strong feeling that you want to do something, especially a feeling that is difficult to control","cn":""},{"en":"a sudden feeling that you would like to do something, especially when this is not sensible or when there is no reason at all to do it","cn":""},{"en":"a sudden strong desire to do something before thinking about whether it is the right or sensible thing to do","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A whim is an odd or fanciful idea, something kooky you suddenly decide to do, like dress up like a chicken or drive to Vegas."}]},"collocations":{"phrases":["ADJ. sudden | slightest The bird's nest is vulnerable to the slightest whim of the weather. | individual, personal | political Funding is su","VERB + WHIM indulge, pander to, satisfy | be subject to, be vulnerable to, depend on | suffer For years she had suffered her husband's whims","PREP. at (sb's) ~ They seem to be able to change the rules of the game at whim. Slaves could be bought and sold at the whim of their masters","PHRASES your every whim The child's parents pandered to his every whim."]},"media":{"uk":"media/ldoce/hwd/bre/4/whim0205.mp3","us":"media/ldoce/hwd/ame/f/whim.mp3"},"examples":[{"en":"My duties seem to change daily at the whim of the boss.","cn":"我的职责似乎随着老板的兴致每天改变。"},{"en":"He was forced to pander to her every whim.","cn":"她每次心血来潮他都不得不依随她。"}],"oxford":{"phon":"wɪm","pos":"noun","senses":[{"en":"a sudden wish to do or have something, especially when it is something unusual or unnecessary","cn":"心血来潮；一时的兴致；突发的奇想","ex":{"en":"He was forced to pander to her every whim.","cn":"她每次心血来潮他都不得不依随她。"}}]}},"whirlpool":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"漩涡","en":"A whirlpool is a small area in a river or the sea where the water is moving quickly round and round, so that objects floating near it are pulled into its centre."},{"pos":"N-COUNT 可数名词","cn":"(很多不愉快或复杂事情构成的)漩涡","en":"You can describe a situation in which a lot of unpleasant or complicated things are happening, and from which it is very difficult to escape, as a whirlpool .","ex":{"en":"They felt they were being sucked into a whirlpool of publicity","cn":"他们觉得好像陷入了一个宣传的漩涡中。"}},{"pos":"N-COUNT 可数名词","cn":"涡旋浴池","en":"A whirlpool bath or a whirlpool is a bath that is specially designed so that the water moves round and round.","ex":{"en":"...a luxurious whirlpool bath with gold taps","cn":"有金制水龙头的豪华涡旋浴池"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a powerful current of water that spins around and can pull things down into it","cn":"漩涡"},{"en":"a large bathtub that makes hot water move in strong currents around your body","cn":"漩涡浴缸﹐涡流浴缸"},{"en":"a very busy situation or a strong emotion, from which it is difficult to escape","cn":"感情的旋涡/纷繁的活动等"}]},"media":{"uk":"media/ldoce/hwd/bre/a/whirlpool0205.mp3","us":"media/ldoce/hwd/ame/9/whirlpool.mp3"},"examples":[{"en":"( figurative ) She felt she was being dragged into a whirlpool of emotion.","cn":"她觉得自己被卷入了感情的漩涡。"},{"en":"people who are caught in a whirlpool of grief","cn":"沉浸在极度悲伤中的人们"}],"oxford":{"phon":"ˈwɜːlpuːl","pos":"noun","senses":[{"en":"a place in a river or the sea where currents of water turn round and round very fast","cn":"（河水或海水的）旋涡","lab":"figurative","ex":{"en":"She felt she was being dragged into a whirlpool of emotion.","cn":"她觉得自己被卷入了感情的旋涡。"}},{"en":"a special bath or swimming pool for relaxing in, in which the water moves in circles","cn":"涡流浴缸；涡流游泳池"}]}},"whisk":{"collins":{"senses":[{"pos":"VERB 动词","cn":"迅速送走;匆匆带走","en":"If you whisk someone or something somewhere, you take them or move them there quickly.","ex":{"en":"He whisked her across the dance floor","cn":"他带着她飞快地穿过舞池。"}},{"pos":"VERB 动词","cn":"搅拌，搅打(鸡蛋、奶油等)","en":"If you whisk something such as eggs or cream, you stir it very fast, often with an electric device, so that it becomes full of small bubbles.","ex":{"en":"Just before serving, whisk the cream","cn":"在上桌之前，要搅打一下奶油。"}},{"pos":"N-COUNT 可数名词","cn":"搅拌器;打蛋器","en":"A whisk is a kitchen tool used for whisking eggs or cream.","ex":{"en":"Using a whisk, mix the yolks and sugar to a smooth paste.","cn":"用打蛋器将蛋黄和糖打成均匀的糊状。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put different substances or liquids together so that they can no longer be separated","cn":""},{"en":"to mix things together so that they form a single substance. Combine is more formal than mix","cn":""},{"en":"to move a spoon or stick around in a liquid, a pan etc, especially when you are mixing things together","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/whisk_n0205.mp3","us":"media/ldoce/hwd/ame/3/whisk1.mp3"},"examples":[{"en":"The waiter whisked away the plates before we had finished.","cn":"服务员没等我们吃完就匆忙把盘子端走了。"},{"en":"Jamie whisked her off to Paris for the weekend.","cn":"杰米匆匆把她带到巴黎去度周末。"}],"oxford":{"phon":"wɪsk","pos":"verb","senses":[{"en":"to mix liquids, eggs, etc. into a stiff, light mass, using a fork or special tool","cn":"搅打，搅动（液体、鸡蛋等）","ex":{"en":"Whisk the egg whites until stiff.","cn":"把蛋白搅打稠。"}},{"en":"to take somebody/something somewhere very quickly and suddenly","cn":"匆匆带走；迅速送走","ex":{"en":"Jamie whisked her off to Paris for the weekend.","cn":"杰米匆匆把她带到巴黎去度周末。"}},{"en":"a kitchen utensil (= a tool) for mixing eggs, etc. very fast","cn":"打蛋器；搅拌器","ex":{"en":"an electric whisk","cn":"电动搅拌器"},"pos":"noun"}]}},"whaler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"捕鲸船","en":"A whaler is a ship which is used in hunting whales."},{"pos":"N-COUNT 可数名词","cn":"捕鲸船船员","en":"A whaler is someone who works on a ship which is used in hunting whales."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who hunts whales","cn":"捕鲸者"},{"en":"a boat used to hunt whales","cn":"捕鲸船"}]},"media":{"uk":"media/ldoce/hwd/bre/7/whaler0205.mp3","us":"media/ldoce/hwd/ame/f/whaler.mp3"},"oxford":{"phon":"ˈweɪlə(r)","pos":"noun","senses":[{"en":"a ship used for hunting whales","cn":"捕鲸船"},{"en":"a person who hunts whales","cn":"捕鲸人"}]}},"whitsun":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"圣灵降临周(复活节后的第七个星期日及接下来的一周)","en":"Whitsun is the seventh Sunday after Easter, and the week that follows that Sunday."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the seventh Sunday after Easter, when Christians celebrate the Holy Spirit coming down from heaven","cn":"圣灵降临节〔复活节后第七个星期日〕"},{"en":"the period around Whitsun","cn":"圣灵降临周"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41whitsun.mp3","us":"media/ldoce/hwd/ame/5/whitsun.mp3"},"oxford":{"phon":"ˈwɪtsn","pos":"noun","senses":[{"en":"the 7th Sunday after Easter and the days close to it","cn":"圣灵降临节，圣神降临节（复活节后的第 7 个星期日前后几天）"}]}},"whimsical":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"怪异的;反复无常的;不切实际的","en":"A whimsical person or idea is unusual, playful, and unpredictable, rather than serious and practical.","ex":{"en":"McGrath remembers his offbeat sense of humor, his whimsical side","cn":"麦格拉思记得他不同寻常的幽默感和他古怪的一面。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unusual or strange and often amusing","cn":"古怪的﹔异想天开的﹐滑稽可笑的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Whimsical means full of or characterized by whims , which are odd ideas that usually occur to you very suddenly. If you decide at the last minute to fly to Europe, you could say you went there on a whim ."}]},"media":{"uk":"media/ldoce/hwd/bre/7/whimsical0205.mp3","us":"media/ldoce/hwd/ame/f/whimsical.mp3"},"examples":[{"en":"Much of his writing has a whimsical quality.","cn":"他的大部分作品都很出奇。"},{"en":"to have a whimsical sense of humour","cn":"有离奇的幽默感"}],"oxford":{"phon":"ˈwɪmzɪkl","pos":"adjective","senses":[{"en":"unusual and not serious in a way that is either funny or annoying","cn":"异想天开的；想入非非的；心血来潮的；滑稽可笑的","ex":{"en":"to have a whimsical sense of humour","cn":"有离奇的幽默感"}}]}},"whelk":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海螺;蛾螺","en":"A whelk is a creature like a snail that is found in the sea near the shore. Whelks have hard shells, and soft bodies which can be eaten."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small sea animal that has a shell and can be eaten","cn":"蛾螺"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41whelk.mp3","us":"media/ldoce/hwd/ame/c/whelk.mp3"},"oxford":{"phon":"welk","pos":"noun","senses":[{"en":"a small shellfish that can be eaten","cn":"蛾螺（有些可食用）"}]}},"wherewithal":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(某一特定用途的)必要设备，必要手段;（尤指）所需资金","en":"If you have the wherewithal for something, you have the means, especially the money, that you need for it.","ex":{"en":"She didn't have the financial wherewithal to do it","cn":"她没有做这件事所需的资金。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the money, skill etc that you need in order to do something","cn":"做某事所需的金钱[技能等]"}]},"vocab":{"pos":"n","senses":[{"en":"If you have the wherewithal to do something, it means you've got what you need to make it happen."}]},"media":{"uk":"media/ldoce/hwd/bre/5/wherewithal0205.mp3","us":"media/ldoce/hwd/ame/b/wherewithal.mp3"},"examples":[{"en":"They lacked the wherewithal to pay for the repairs.","cn":"他们缺少维修费。"},{"en":"Does Cath have the creative wherewithal to make it as a solo act?","cn":"凯思有没有可以进行个人秀的创造力？"}]},"whore":{"collins":{"senses":[{"pos":"","cn":"同 prostitute","en":"A whore is the same as a prostitute ."},{"pos":"","cn":"淫妇;婊子","en":"If you call a woman a whore, you disapprove of her because you consider her sexual behaviour to be immoral or unacceptable."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone, usually a woman, who has sex with people for money","cn":""},{"en":"a woman who has sex with men for money","cn":""},{"en":"a woman who has sex with men for money and arranges to meet them by telephone","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"In the original sense, a whore is a prostitute: someone who has sex for money. The word has since broadened to mean anyone who is money-hungry."}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdewhore.mp3","us":"media/ldoce/hwd/ame/9/whore.mp3"},"oxford":{"phon":"hɔː(r)","pos":"noun","senses":[{"en":"a woman who works as a prostitute","cn":"妓女","lab":"old-fashioned"},{"en":"an offensive word used to refer to a woman who has sex with a lot of men","cn":"乱搞男女关系的女人；破鞋","lab":"taboo, offensive，，"}]}},"whammy":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(困难或打击)同时发生，相继发生;祸不单行","en":"Whammy is used in expressions such as double whammy and triple whammy to indicate that two or three unpleasant or difficult situations occur at the same time, or occur one after the other.","ex":{"en":"This is a double whammy for public sector workers","cn":"对于公共部门的工作人员而言可谓祸不单行。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"two or three unpleasant things that happen at or around the same time and cause problems or difficulties for someone or for people in general","cn":"双重/三重倒霉事"},{"en":"to use magic to make someone have bad luck","cn":"用魔力使某人倒霉"}]},"media":{"uk":"media/ldoce/hwd/bre/8/whammy0205.mp3","us":"media/ldoce/hwd/ame/0/laadwhammy.mp3"},"examples":[{"en":"With this government we've had a double whammy of tax increases and benefit cuts.","cn":"自从这任政府上台以来，我们又是增加税收又是减少补贴，倒了双倍的霉。"},{"en":"The government’s policy is higher tax and higher interest rates. It’s a double whammy.","cn":"政府的政策是高税收和高利率﹐这真是双重打击。"}],"oxford":{"phon":"ˈwæmi","pos":"noun","senses":[{"en":"an unpleasant situation or event that causes problems for somebody/something","cn":"晦气；倒霉事","ex":{"en":"With this government we've had a double whammy of tax increases and benefit cuts.","cn":"自从这任政府上台以来，我们又是增加税收又是减少补贴，倒了双倍的霉。"}}]}},"whet":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"刺激(某人)对…的欲望;激发（某人）对…的兴趣","en":"If someone or something whets your appetite for a particular thing, they increase your desire to have it or know about it, especially by giving you an idea of what it is like.","ex":{"en":"A really good catalogue can also whet customers' appetites for merchandise.","cn":"一份真正好的商品目录也可以激起顾客购买的欲望。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if an experience whets your appetite for something, it increases your desire for it","cn":"引起某人(对某事物)的欲望"},{"en":"to make the edge of a blade sharp","cn":"将〔刀刃〕磨快"}]},"vocab":{"pos":"v","senses":[{"en":"To whet is to sharpen. You could whet a knife's blade with a whetting stone, or you could whet your appetite by having some Doritos."}]},"media":{"uk":"media/ldoce/hwd/bre/d/whet0205.mp3","us":"media/ldoce/hwd/ame/2/wet1.mp3"},"examples":[{"en":"The book will whet your appetite for more of her work.","cn":"你看了这本书就会更想多读她的著作。"},{"en":"The view from the Quai bridge had whetted my appetite for a trip on the lake.","cn":"从凯伊大桥望过去的景色勾起了我到湖上一游的念头。"}],"oxford":{"phon":"wet","pos":"verb","senses":[{"en":"to increase your desire for or interest in something","cn":"刺激…的欲望；增强…的兴趣","ex":{"en":"The book will whet your appetite for more of her work.","cn":"你看了这本书就会更想多读她的著作。"}}]}},"whist":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"惠斯特牌（两人一组玩的扑克牌游戏）","en":"Whist is a card game in which people play in pairs against each other."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a card game for four players in two pairs, in which each pair tries to win the most trick s","cn":"惠斯特纸牌戏〔由四人组成两方对打〕"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41whist.mp3","us":"media/ldoce/hwd/ame/0/whist.mp3"},"oxford":{"phon":"wɪst","pos":"noun","senses":[{"en":"a card game for two pairs of players in which each pair tries to win the most cards","cn":"惠斯特（一种由两对游戏者玩的纸牌游戏）"}]}},"white-hot":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"白热的;炽热的","en":"If something is white-hot, it is extremely hot.","ex":{"en":"It is important to get the coals white-hot before you start.","cn":"在动手之前把炭火烧旺很重要。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"white-hot metal is so hot that it shines white 〔","cn":"金属〕白热的"},{"en":"involving a lot of activity or strong feelings","cn":"激烈的﹐白热化的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41white-hot.mp3","us":"media/ldoce/hwd/ame/d/white-hot.mp3"},"examples":[{"en":"white-hot passion","cn":"炽热的激情"}],"oxford":{"phon":"ˌwaɪt ˈhɒt","pos":"adjective","senses":[{"en":"so hot that it looks white","cn":"白热的；白炽的"},{"en":"very strong and intense","cn":"白热化的；极其激烈的"}]}},"whiteness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to be suddenly frightened by something that happens","cn":""},{"en":"to suddenly become so frightened that you cannot think clearly, especially if this makes you do something dangerous or stupid","cn":""},{"en":"to make a sudden movement because you are surprised and frightened by something that happens very suddenly","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/white_las2_br.mp3","us":"media/ldoce/hwd/ame/0/white1.mp3"},"examples":[{"en":"Are you OK? You’re white as a sheet (= extremely pale ) .","cn":""},{"en":"Her voice shook, and her face was white with anger.","cn":""}],"oxford":{"phon":"ˈwaɪtnəs","pos":"noun","senses":[{"en":"the quality of being white or very light in colour","cn":"白;苍白","ex":{"en":"The whiteness of her skin was enhanced by the darkness of her hair.","cn":"深色的头发衬托出她皮肤的白度。"}}]}},"whittle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"削(木头等)","en":"If you whittle something from a piece of wood, you carve it by cutting pieces off the wood with a knife.","ex":{"en":"He whittled a new handle for his ax","cn":"他给斧头削了一个新把手。"}},{"pos":"","cn":"","en":"相关词组：whittle away whittle down"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to cut shapes out of solid wood or stone","cn":""},{"en":"to cut a piece of wood into a particular shape by cutting off small pieces with a small knife","cn":""},{"en":"to gradually reduce the amount or value of something, especially money, wages, or profits over a period of time","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To whittle is to pare or carve away. Wood carvers whittle pieces of wood, removing bit by bit until what's left is a sailor with a yellow raincoat or a lone wolf howling at the moon."}]},"media":{"uk":"media/ldoce/hwd/bre/5/whittle0205.mp3","us":"media/ldoce/hwd/ame/e/whittle.mp3"},"examples":[{"en":"I finally managed to whittle down the names on the list to only five.","cn":"我最后总算把名单上的名字减少到了只有五个。"},{"en":"He whittled a simple toy from the piece of wood.","cn":"他把那块木头削成了一个简易的玩具。"}],"oxford":{"phon":"ˈwɪtl","pos":"verb","senses":[{"en":"to form a piece of wood, etc. into a particular shape by cutting small pieces from it","cn":"把（木头等）削成…","ex":{"en":"He whittled a simple toy from the piece of wood.","cn":"他把那块木头削成了一个简易的玩具。"}}]}},"whiten":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)变白","en":"When something whitens or when you whiten it, it becomes whiter or paler in colour.","ex":{"en":"Her knuckles whiten as she clenches her hands harder.","cn":"她的手握得越来越紧，指节都变白了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to become more white, or to make something do this （","cn":"使）变白﹔漂白"}]},"media":{"uk":"media/ldoce/hwd/bre/4/whiten0205.mp3","us":"media/ldoce/hwd/ame/3/whiten.mp3"},"examples":[{"en":"He gripped the wheel until his knuckles whitened.","cn":"他紧紧握住方向盘，握得指关节都变白了。"},{"en":"Snow had whitened the tops of the trees.","cn":"大雪把树冠变成了白色。"}],"oxford":{"phon":"ˈwaɪtn","pos":"verb","senses":[{"en":"to become white or whiter; to make something white or whiter","cn":"（使）变白，变得更白","ex":{"en":"He gripped the wheel until his knuckles whitened.","cn":"他紧紧握住方向盘，握得指关节都变白了。"}}]}},"whimsy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"奇思异想;不同寻常的行为","en":"Whimsy is behaviour which is unusual, playful, and unpredictable, rather than having any serious reason or purpose behind it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a way of thinking, behaving, or doing something that is unusual, strange, and often amusing","cn":"古怪〔而往往好笑的〕想法﹔古怪[荒诞]行径"}]},"vocab":{"pos":"n","senses":[{"en":"Whimsy is what a person who's a dreamer and out of step with the real world might have lots of. People who are full of whimsy are odd, but often fanciful and lovely, like Harry Potter's friend Luna Lovegood."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41whimsy.mp3","us":"media/ldoce/hwd/ame/2/whimsy.mp3"},"examples":[{"en":"a sense of fancy and whimsy","cn":"稀奇古怪的想象力"}],"oxford":{"phon":"ˈwɪmzi","pos":"noun","senses":[{"en":"a way of thinking or behaving or a style of doing something that is unusual and not serious, in a way that is either funny or annoying","cn":"怪念头；古怪可笑的举动；吊儿郎当；随心所欲"}]}},"whitewash":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(粉刷用的)石灰水，白涂料","en":"Whitewash is a mixture of lime or chalk and water that is used for painting walls white."},{"pos":"VERB 动词","cn":"用石灰水粉刷","en":"If a wall or building has been whitewashed, it has been painted white with whitewash.","ex":{"en":"The walls had been whitewashed.","cn":"墙已经用石灰水刷过了。"}},{"pos":"VERB 动词","cn":"粉饰;掩饰","en":"If you say that people whitewash something, you are accusing them of hiding the unpleasant facts or truth about it in order to make it acceptable.","ex":{"en":"The administration is whitewashing the regime's actions","cn":"政府在粉饰该政权的行为。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"粉饰;掩饰","en":"Whitewash is an attempt to hide the unpleasant facts or truth about someone or something.","ex":{"en":"He pledged that there would be no whitewash and that the police would carry out a full investigation","cn":"他保证将不会有任何掩饰，并且警方将进行全面调查。"}},{"pos":"VERB 动词","cn":"轻易战胜；使（对手）得零分","en":"In sports, if a player or team whitewashes an opponent, they win very easily, and their opponent does not get any points at all.","ex":{"en":"Not since 1988 had she whitewashed an opponent in her opening match","cn":"自1988年以来她还从未在开场赛中让对手吃过鸭蛋。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a deliberate plan to prevent mistakes or embarrassing information, especially about politicians or other people in official positions, from being publicly known","cn":""},{"en":"an attempt by a government or official committee to hide the true facts of a situation from the public, especially when there was supposed to have been an official and fair examination of these facts","cn":""},{"en":"something that you do or say as a way of hiding your true actions or intentions, especially when these are illegal or dishonest","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/whitewash_v0205.mp3","us":"media/ldoce/hwd/ame/7/whitewash1.mp3"},"examples":[{"en":"His wife had wanted to whitewash his reputation after he died.","cn":"他妻子在他死后本来想粉饰他的名声。"},{"en":"The opposition claimed the report was a whitewash.","cn":"反对派声称这份报告文过饰非。"}],"oxford":{"phon":"ˈwaɪtwɒʃ","pos":"noun","senses":[{"en":"a mixture of chalk or lime and water, used for painting houses and walls white","cn":"（粉刷用的）石灰水，白涂料","g":"[uncountable]"},{"en":"an attempt to hide unpleasant facts about somebody/something","cn":"粉饰；掩盖","g":"[uncountable, singular]","lab":"disapproving","ex":{"en":"The opposition claimed the report was a whitewash.","cn":"反对派声称这份报告文过饰非。"}},{"en":"(in sport) a victory in every game in a series","cn":"（在体育比赛中接连击败对手的）全胜，完胜","g":"[countable, usually singular]","lab":"especially British English, informal，，","ex":{"en":"a 7–0 whitewash","cn":"7:0 全胜"}},{"en":"to cover something such as a wall with whitewash","cn":"粉刷（墙壁等）；刷石灰水","pos":"verb"},{"en":"to try to hide unpleasant facts about somebody/something; to try to make something seem better than it is","cn":"掩饰；粉饰","lab":"disapproving","ex":{"en":"His family tried to whitewash his reputation after he died.","cn":"他死后，他的家人试图粉饰他的名誉。"},"pos":"verb"},{"en":"to defeat an opponent in every game in a series","cn":"（在系列比赛中）完全击败，完胜","lab":"especially British English, informal，，","pos":"verb"}]}},"wheedle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"哄骗;劝诱","en":"If you say that someone wheedles, you mean that they try to persuade someone to do or give them what they want, for example by saying nice things that they do not mean.","ex":{"en":"Cross decided to beg and wheedle a bit","cn":"克罗斯决定用上点乞求和哄骗。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to persuade someone to do or give you something, for example by saying nice things to them that you do not mean – used to show disapproval","cn":"哄骗﹐诓骗〔含贬义〕"}]},"vocab":{"pos":"v","senses":[{"en":"To wheedle is to sweet talk, or flatter someone in the hopes of getting something in return. You might try to wheedle a meter maid into not giving you a parking ticket. Good luck with that."}]},"media":{"uk":"media/ldoce/hwd/bre/9/wheedle0205.mp3","us":"media/ldoce/hwd/ame/1/wheedle.mp3"},"examples":[{"en":"She wheedled me into lending her my new coat.","cn":"她用花言巧语哄我把新大衣借给了她。"},{"en":"The kids can always wheedle money out of their father.","cn":"孩子们总是能从父亲那里哄出钱来。"}],"oxford":{"phon":"ˈwiːdl","pos":"verb","senses":[{"en":"to persuade somebody to give you something or do something by saying nice things that you do not mean","cn":"（用言语）哄","ex":{"en":"The kids can always wheedle money out of their father.","cn":"孩子们总是能从父亲那里哄出钱来。"}}]}},"whiskery":{"lemma":"whiskered"},"wheelhouse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(轮船的)驾驶室","en":"A wheelhouse is a small room or shelter on a ship or boat, where the wheel used for steering the boat is situated."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the place on a ship where the captain stands at the wheel 〔","cn":"船上的〕驾驶室﹐操舵室"}]},"vocab":{"pos":"n","senses":[{"en":"A wheelhouse is literally a small enclosure on a boat or ship that houses the steering wheel. The captain navigates the ship from the wheelhouse . On land, though, something in your wheelhouse is in your area of expertise."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41wheelhouse.mp3","us":"media/ldoce/hwd/ame/4/wheelhouse.mp3"},"oxford":{"phon":"ˈwiːlhaʊs","pos":"noun","senses":[{"en":"a small cabin with walls and a roof on a ship where the person controlling the direction in which the ship moves stands at the wheel","cn":"（船上的）操舵室，驾驶室"},{"en":"a person's area of expert knowledge or experience","cn":"（个人的）专长，强项","lab":"North American English","ex":{"en":"The movie has superstar DiCaprio in a role that is right in his wheelhouse.","cn":"这部电影由超级巨星迪卡普里奥饰演一个他十分擅长的角色。"}},{"en":"if a pitch (= throw of the ball) is in your wheelhouse, it is in the area where it is easiest to hit","cn":"最佳击球区域","ex":{"en":"The ball was in Escobar's wheelhouse and he hammered it to right-center field.","cn":"球在埃斯科瓦尔的驾驶室里，他将球击向右中场。"}}]}},"whacky":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"another spelling of wacky wacky","cn":"的另一种拼法"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld5_whacky.mp3","us":"media/ldoce/hwd/ame/c/ld5_whacky.mp3"},"oxford":{"phon":"ˈwæki","pos":"adjective","senses":[{"en":"funny in a slightly crazy way","cn":"古怪的；滑稽可笑的；疯疯癫癫的"}]}},"wholemeal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"全麦的","en":"Wholemeal flour is made from the complete grain of the wheat plant, including the outer part. Wholemeal bread or pasta is made from wholemeal flour.","ex":{"en":"...a slice of wholemeal toast.","cn":"一片全麦吐司"}},{"pos":"N-UNCOUNT 不可数名词","cn":"全麦面包；全麦面粉","en":"Wholemeal means wholemeal bread or wholemeal flour.","ex":{"en":"...one slice of white and one of wholemeal.","cn":"一片白面包和一片全麦面包"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"wholemeal flour or bread uses all of the grain, including the outer layer 〔","cn":"面粉或面包〕全麦的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/wholemeal0205.mp3","us":"media/ldoce/hwd/ame/b/ld41wholemeal.mp3"},"oxford":{"phon":"ˈhəʊlmiːl","pos":"adjective","senses":[{"en":"wholemeal bread or flour contains the whole grains of wheat, etc. including the husk","cn":"全麦的"}]}},"wheelchair":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"轮椅","en":"A wheelchair is a chair with wheels that you use in order to move about in if you cannot walk properly, for example because you are disabled or sick."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a chair with wheels, used by people who cannot walk","cn":"轮椅"}]},"collocations":{"phrases":["ADJ. electric, motorized, powered","VERB + WHEELCHAIR use | manoeuvre Anthony manoeuvred his wheelchair out from behind his desk. | push | be confined to He's been confined to ","WHEELCHAIR + NOUN access | user better access for wheelchair users | athlete","PREP. by ~ In town, she gets about by wheelchair. | in a/the ~ It's hard to get around if you're in a wheelchair.","PHRASES accessible by wheelchair, wheelchair accessible facilities/vehicles, etc."]},"media":{"img":["media/ldoce/img/wheelchair.jpg"],"uk":"media/ldoce/hwd/bre/0/wheelchair0205.mp3","us":"media/ldoce/hwd/ame/c/wheelchair.mp3"},"examples":[{"en":"He's been confined to a wheelchair since the accident.","cn":"他从车祸以后就离不开轮椅了。"},{"en":"Does the hotel have wheelchair access?","cn":"这家旅馆有轮椅通道吗？"}],"oxford":{"phon":"ˈwiːltʃeə(r)","pos":"noun","senses":[{"en":"a special chair with wheels, used by people who cannot walk because of illness, an accident, etc.","cn":"轮椅","ex":{"en":"In town, she gets about by wheelchair.","cn":"在城里 ，她坐 轮椅四处转。"}}]}},"whitehall":{"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"怀特霍尔(伦敦一街名，许多政府机关所在地)；白厅(指英国政府)","en":"Whitehall is the name of a street in London in which there are many government offices. You can also use Whitehall to mean the British Government itself.","ex":{"en":"...people with banners marching down Whitehall","cn":"打着标语在怀特霍尔街上行进的人们"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the British government, especially the government departments rather than parliament or the prime minister","cn":"白厅〔英国政府﹐尤指政府部门而非议会或首相〕"},{"en":"the street in London where many of the government departments are","cn":"怀特霍尔〔伦敦街道名﹐为英国许多政府部门所在地〕"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41whitehall.mp3","us":"media/ldoce/hwd/ame/4/ld41whitehall.mp3"},"examples":[{"en":"Whitehall are/is refusing to comment.","cn":"白厅拒绝发表评论。"}],"oxford":{"phon":"ˈwaɪthɔːl","pos":"noun","senses":[{"en":"a street in London where there are many government offices","cn":"白厅（伦敦的一条街，政府机关所在地）","g":"[uncountable]","ex":{"en":"The changes will affect a number of Whitehall departments.","cn":"这些变化将影响白厅的许多部门。"}},{"en":"a way of referring to the British government or the officials who work for it","cn":"白厅（指英国政府或其官员）","g":"[uncountable + singular or plural verb]","ex":{"en":"Whitehall are/is refusing to comment.","cn":"白厅拒绝发表评论。"}}]}},"whack":{"collins":{"senses":[{"pos":"VERB 动词","cn":"重打;重击","en":"If you whack someone or something, you hit them hard.","ex":{"en":"You really have to whack the ball","cn":"你真的需要猛击球才行。"}},{"pos":"N-SING 单数名词","cn":"份额；一份","en":"Your whack of something is your share of it.","ex":{"en":"The majority of people in this country pay their whack","cn":"该国大部分人尽了他们的一份力。"}},{"pos":"VERB 动词","cn":"(轻松地)打败，击败","en":"If someone whacks you, they defeat you easily in a game or competition.","ex":{"en":"We got whacked. On paper we should have wiped the floor with them.","cn":"我们被轻易地击败了。按理说我们本应该大败他们。"}},{"pos":"VERB 动词","cn":"谋杀","en":"To whack someone means to kill them.","ex":{"en":"His mother was murdered. Yeah, she got whacked. Snuffed out.","cn":"他母亲是被谋杀的。是的，是被人干掉的，弄死的。"}},{"pos":"PHRASE 短语","cn":"不正常的;紊乱的；出故障的","en":"If something is out of whack, it is not working properly, often because its natural balance has been upset.","ex":{"en":"The ecosystem will be thrown out of whack.","cn":"生态系统将会失去平衡。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to hit a door or window with your closed hand in order to attract the attention of the people inside","cn":""},{"en":"to hit a surface. Strike is more formal than hit and is mainly used in written English","cn":""},{"en":"to hit something very hard","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/whack_v0205.mp3","us":"media/ldoce/hwd/ame/0/whack1.mp3"},"examples":[{"en":"Don't leave all the work to her. Everyone should do their fair whack.","cn":"别把所有的工作都让她做。大家应合理地分担一下。"},{"en":"All the traveling had thrown my body out of whack.","cn":"这一路旅行已经使我的身体出了毛病。"}],"oxford":{"phon":"wæk","pos":"verb","senses":[{"en":"to hit somebody/something very hard","cn":"猛打；重击；狠揍","lab":"informal","ex":{"en":"She whacked him with her handbag.","cn":"她用手提包狠狠地打他。"}},{"en":"to put something somewhere without much care","cn":"草草放下","lab":"informal","ex":{"en":"Just whack your bags in the corner.","cn":"就把你的包丢在角落里吧。"}},{"en":"to murder somebody","cn":"谋杀","lab":"North American English, slang，，"},{"en":"the act of hitting somebody/something hard; the sound made by this","cn":"重击；重击声","ex":{"en":"He gave the ball a good whack.","cn":"他猛击了一下球。"},"pos":"noun"},{"en":"a share of something; an amount of something","cn":"份儿；一份；量","lab":"British English","ex":{"en":"Don't leave all the work to her. Everyone should do their fair whack.","cn":"别把所有的工作都让她做。大家应合理分担一下。"},"pos":"noun"}]}},"whirlwind":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(陆地或海洋上的)旋风，旋流","en":"A whirlwind is a tall column of air which spins round and round very fast and moves across the land or sea."},{"pos":"N-COUNT 可数名词","cn":"一连串的突发事件","en":"You can describe a situation in which a lot of things happen very quickly and are very difficult for someone to control as a whirlwind .","ex":{"en":"I had been running around southern England in a whirlwind of activity","cn":"我一直奔忙于英格兰南部地区，疲于应对一连串的活动。"}},{"pos":"ADJ 形容词","cn":"旋风般的;匆匆忙忙的;快速的","en":"A whirlwind event or action happens or is done much more quickly than normal.","ex":{"en":"He got married after a whirlwind romance.","cn":"在一场旋风式的恋爱后他很快就结婚了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an extremely strong wind that moves quickly with a circular movement, causing a lot of damage","cn":"旋风"},{"en":"a situation in which you experience a lot of different emotions, or a lot of different things happen, one after another","cn":"纷乱的情绪/纷繁的活动"},{"en":"a whirlwind situation or event happens very quickly","cn":"快速的﹔匆忙的﹔旋风式的"}]},"vocab":{"pos":"n","senses":[{"en":"You can describe a tornado — a swirling vortex of air — as a powerful whirlwind , which is literally wind that whirls around in a narrow upright tube shape as it moves over the ground."}]},"media":{"uk":"media/ldoce/hwd/bre/2/whirlwind_n0205.mp3","us":"media/ldoce/hwd/ame/e/whirlwind1.mp3"},"examples":[{"en":"To recover from the divorce, I threw myself into a whirlwind of activities.","cn":"为了从离婚中恢复过来，我马不停蹄地投身于一系列的活动。"},{"en":"a whirlwind tour of America","cn":"旋风式的美国之行"}],"oxford":{"phon":"ˈwɜːlwɪnd","pos":"noun","senses":[{"en":"a very strong wind that moves very fast in circles and causes a lot of damage","cn":"旋风；旋流"},{"en":"a situation or series of events where a lot of things happen very quickly","cn":"一片忙乱","ex":{"en":"To recover from the divorce, I threw myself into a whirlwind of activities.","cn":"为了从离婚中恢复过来，我马不停蹄地投身于一系列的活动。"}},{"en":"happening very fast","cn":"快速的；匆匆忙忙的；旋风似的","ex":{"en":"a whirlwind romance","cn":"旋风式恋爱"},"pos":"adjective"}]}},"wheelbarrow":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(园艺等用的) 手推车，独轮推车","en":"A wheelbarrow is a small open cart with one wheel and handles that is used for carrying things, for example in the garden."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small cart with one wheel and two handles that you use outdoors to carry things, especially in the garden","cn":"独轮手推车"}]},"media":{"img":["media/ldoce/img/wheelbarrow.jpg","media/thumb/wheelbarrow.jpg"],"uk":"media/ldoce/hwd/bre/3/wheelbarrow0205.mp3","us":"media/ldoce/hwd/ame/c/wheelbarrow.mp3"},"oxford":{"phon":"ˈwiːlbærəʊ","pos":"noun","senses":[{"en":"a large open container with a wheel and two handles that you use outside to carry things","cn":"独轮手推车","ex":{"en":"She took the chest home in a wheelbarrow.","cn":"她用独轮车把箱子带回家。"}}]}},"whence":{"collins":{"senses":[{"pos":"QUEST 疑问词","cn":"从何处;来自何方","en":"Whence means from where.","ex":{"en":"No one ordered him back whence he came.","cn":"没有人命令过他从哪里来回哪里去。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"from where","cn":"从哪里"}]},"vocab":{"pos":"adv","senses":[{"en":"Use the adverb whence as an old-fashioned way to say \"from which\" or \"from where.\" If you found a hundred dollar bill on the ground, you might ask, \" Whence did this money come?\""}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41whence.mp3","us":"media/ldoce/hwd/ame/4/ld41whence.mp3"},"examples":[{"en":"They returned whence they had come.","cn":"他们从哪里来又回到哪里去了。"},{"en":"I walked to Rainbagh, whence I could complete the journey by car.","cn":"我步行至雷恩巴夫﹐从那里我可以开车走完全程。"}],"oxford":{"phon":"wens","pos":"adverb","senses":[{"en":"from where","cn":"从何处；从哪里","ex":{"en":"They returned whence they had come.","cn":"他们从哪里来又回到哪里去了。"}}]}},"wholehearted":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"全心全意的","en":"If you support or agree to something in a wholehearted way, you support or agree to it enthusiastically and completely.","ex":{"en":"The Government deserves our wholehearted support for having taken a step in this direction.","cn":"政府已朝这个方向迈进了一步，理应得到我们的全力支持。"}}]},"examples":[{"en":"The plan was given wholehearted support.","cn":"这项计划得到了全心全意的支持。"},{"en":"to agree wholeheartedly","cn":"完全同意"}],"oxford":{"phon":"ˌhəʊlˈhɑːtɪd","pos":"adjective","senses":[{"en":"complete and enthusiastic","cn":"全心全意的；赤诚的","ex":{"en":"The plan was given wholehearted support.","cn":"这项计划得到了全心全意的支持。"}}]}},"whir":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"another spelling of whirr whirr","cn":"的另一种拼法"}]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdewhir.mp3","us":"media/ldoce/hwd/ame/b/were.mp3"},"oxford":{"phon":"wɜː(r)","pos":"verb","senses":[{"en":"to make a continuous, low sound like the parts of a machine moving","cn":"嗡嗡地响；呼呼地响","ex":{"en":"The clock began to whir before striking the hour.","cn":"钟在敲响整点前先嘎啦嘎啦地响。"}},{"en":"a continuous, low sound, for example the sound made by the regular movement of a machine or the wings of a bird","cn":"嗡嗡声；呼呼声","ex":{"en":"the whir of a motor","cn":"发动机的嗡嗡声"},"pos":"noun"}]}},"wholeness":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"整体性，完整性","en":"Wholeness is the quality of being complete or a single unit and not broken or divided into parts.","ex":{"en":"...the need for wholeness and harmony in mind, body and spirit.","cn":"保持头脑、身体和精神和谐统一的需要"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"all of something -- used especially with uncountable nouns","cn":""},{"en":"all of something that is large, long, or has a lot of parts, for example a large area of land, a long period of time, or a large group of people","cn":""},{"en":"all of something -- use this especially to show that you are annoyed or surprised by this","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdewhole.mp3","us":"media/ldoce/hwd/ame/4/hole1.mp3"},"examples":[{"en":"You have your whole life ahead of you!","cn":""},{"en":"His whole attitude bugs me.","cn":""}],"oxford":{"phon":"ˈhəʊlnəs","pos":"noun","senses":[{"en":"the quality of being whole or complete","cn":"整体性，完整性","ex":{"en":"People come here seeking spiritual wholeness.","cn":"人们来到这里寻求精神上的完整。"}}]}},"whoosh":{"collins":{"senses":[{"pos":"EXCLAM 感叹语","cn":"呼的一声；嗖的一下子","en":"People sometimes say 'whoosh' when they are emphasizing the fact that something happens very suddenly or very fast.","ex":{"en":"Then came the riders amid even louder cheers and whoosh! It was all over.","cn":"在更大的欢呼声中骑手们冲过来了，只听呼的一声，就全部飞奔而过！"}},{"pos":"VERB 动词","cn":"迅速移动;突然移动","en":"If something whooshes somewhere, it moves there quickly or suddenly.","ex":{"en":"Cool air whooshes up through the grates on the street","cn":"冷空气吹得大街上的格栅呜呜作响。"}},{"pos":"N-SING 单数名词","cn":"(风的)呼呼;（水的)哗哗","en":"A whoosh of air or water is a sudden rush of it.","ex":{"en":"...the whoosh and murmur of the wind through the trees","cn":"风吹过树林的呼啸呜咽"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move very fast with a soft rushing sound","cn":"呼呼地飞快移动"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41whoosh.mp3","us":"media/ldoce/hwd/ame/6/whoosh1.mp3"},"examples":[{"en":"There was a whoosh as everything went up in flames. “","cn":"呼”的一声，一切都毁于火海。"},{"en":"There was a whoosh as everything went up in flames.","cn":""}],"oxford":{"phon":"wʊʃ","pos":"noun","senses":[{"en":"the sudden movement and sound of air or water rushing past","cn":"（风吹）呼呼；（水流）哗哗","ex":{"en":"a whoosh of air","cn":"呼的一口气"}},{"en":"to move very quickly with the sound of air or water rushing","cn":"（空气）呼呼地移动；（水）哗哗地流","pos":"verb"}]}},"whisker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(猫、鼠等动物的)胡须","en":"The whiskers of an animal such as a cat or a mouse are the long stiff hairs that grow near its mouth."},{"pos":"N-PLURAL 复数名词","cn":"连鬓胡子;络腮胡子","en":"You can refer to the hair on a man's face, especially on the sides of his face, as his whiskers .","ex":{"en":"...wild, savage-looking fellows, with large whiskers, unshaven beards, and dirty faces.","cn":"长着浓密的络腮胡子，胡须未刮且脸上脏兮兮的看起来很粗野的家伙"}},{"pos":"N-SING 单数名词","cn":"微小的数量；一丝；一点儿","en":"You can use whisker in expressions such as by a whisker or within a whisker of to indicate that something happened or is true, but only by a very small amount or degree.","ex":{"en":"A new pet census showed that cats now outnumber dogs by a whisker (7 million to 6.9 million)","cn":"新的宠物普查显示出猫的数量略微超过了狗的数量(700万比690万)。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the long stiff hairs that grow near the mouth of a cat, mouse etc 〔","cn":"猫﹑老鼠等嘴边的〕须"},{"en":"one of the hairs that grow on a man’s face 〔","cn":"男人的〕连鬓胡子﹐颊须﹐髯"},{"en":"to win or lose by a very small amount","cn":"以微弱之差获胜/落败"}]},"media":{"uk":"media/ldoce/hwd/bre/1/whisker0205.mp3","us":"media/ldoce/hwd/ame/3/whisker.mp3"},"examples":[{"en":"They came within a whisker of being killed.","cn":"他们险些丢了性命。"},{"en":"Schmidt finished second, losing by a whisker in the final event.","cn":"施密特在最后的项目中以微弱差距落败﹐屈居第二。"}],"oxford":{"phon":"ˈwɪskə(r)","pos":"noun","senses":[{"en":"any of the long, stiff hairs that grow near the mouth of a cat, mouse, etc.","cn":"（猫、鼠等的）须","g":"[countable]"},{"en":"the hair growing on a man’s face, especially on the sides of his face","cn":"络腮胡子；连鬓胡子","g":"[plural]","lab":"old-fashioned or humorous"}]}},"wheezy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"气喘吁吁的;喘息的","en":"A wheezy cough or laugh comes from someone who has difficulty breathing, so it makes a whistling sound."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making a noisy sound in your throat or chest, because you cannot breathe easily","cn":"气喘的﹔发出喘息声的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41wheezy.mp3","us":"media/ldoce/hwd/ame/d/wheezy.mp3"},"examples":[{"en":"I'm wheezy today.","cn":"我今天感到喘不上气来。"},{"en":"a wheezy cough","cn":"喘鸣性咳"}],"oxford":{"phon":"ˈwiːzi","pos":"adjective","senses":[{"en":"making the high, whistling sound that your chest makes when you cannot breathe easily","cn":"喘息的；喘鸣的；气喘吁吁的；呼哧呼哧响的","ex":{"en":"I'm wheezy today.","cn":"我今天感到喘不上气来。"}}]}},"whoopee":{"collins":{"senses":[{"pos":"EXCLAM 感叹语","cn":"(非常开心或激动时的感叹语)哈哈","en":"People sometimes shout 'whoopee' when they are very happy or excited.","ex":{"en":"I can have a lie in tomorrow. Whoopee!","cn":"我明天能睡懒觉了，哈哈！"}}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a shout of happiness","cn":"哈哈﹐好呀〔高兴的喊叫〕"},{"en":"to go out and enjoy yourself 〔","cn":"外出〕狂欢作乐"},{"en":"to have sex","cn":"干那事〔指做爱〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld44whoopee.mp3","us":"media/ldoce/hwd/ame/f/l3whoopee.mp3"},"examples":[{"en":"Whoopee, we've won!","cn":"哈哈，我们赢了！"}],"oxford":{"phon":"wʊˈpiː","pos":"exclamation","senses":[{"en":"used to express happiness","cn":"（表示高兴）哈哈","ex":{"en":"Whoopee, we've won!","cn":"哈哈，我们赢了！"}}]}},"whirr":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(机器、昆虫翅膀等)发出呼呼声，嗡嗡作响","en":"When something such as a machine or an insect's wing whirrs, it makes a series of low sounds so quickly that they seem like one continuous sound.","ex":{"en":"The camera whirred and clicked.","cn":"相机发出嗡嗡声和咔嚓声。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a continuous sound, for example, like the sound made by bees","cn":""},{"en":"to make a soft, low continuous sound like the sound made by some electric or electronic equipment","cn":""},{"en":"to make a fairly quiet, regular sound like something turning very quickly and beating against the air","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/whirr0205.mp3","us":"media/ldoce/hwd/ame/c/whirr.mp3"},"examples":[{"en":"The clock began to whirr before striking the hour.","cn":"钟在打点前先嘎啦嘎啦地响起来。"},{"en":"There was a whirring of machinery.","cn":"有机器发出的嗡嗡声。"}],"oxford":{"phon":"wɜː(r)","pos":"verb","senses":[{"en":"to make a continuous low sound like the parts of a machine moving","cn":"嗡嗡地响；呼呼地响","ex":{"en":"Three large fans whirred overhead in the afternoon heat.","cn":"午后的酷热中，三把大风扇在头顶呼呼地响。"}}]}},"whetstone":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"磨刀石","en":"A whetstone is a stone which is used for sharpening knives or other tools that have a blade."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a stone used to make the blade of cutting tools sharp","cn":"磨刀石"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41whetstone.mp3","us":"media/ldoce/hwd/ame/7/whetstone.mp3"},"oxford":{"phon":"ˈwetstəʊn","pos":"noun","senses":[{"en":"a stone that is used to make tools, knives and weapons sharp","cn":"磨刀石"}]}},"whit":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"一点也不;完全不","en":"You say not a whit or not one whit to emphasize that something is not the case at all.","ex":{"en":"He cared not a whit for the social, political or moral aspects of literature","cn":"他毫不在乎文学的社会、政治或道德层面。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"同 Whitsun","en":"Whit means the same as Whitsun .","ex":{"en":"The orchestra gave its first performance on Whit Monday.","cn":"乐团在周一的圣灵降临节举行了首场演出。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"not at all","cn":"一点不﹐毫不﹐根本不"}]},"vocab":{"pos":"n","senses":[{"en":"Whit means a small tiny part of––as dregs is to liquid, whit it to everything else. You might feel the last whit of your confidence depart when your teacher hands out the 32-page final exam."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41whit2.mp3","us":"media/ldoce/hwd/ame/8/whit.mp3"},"examples":[{"en":"Whit Monday","cn":"圣灵降临节后的第一个星期一"},{"en":"Sara had not changed a whit.","cn":"萨拉一点也没变。"}],"oxford":{"phon":"wɪt","pos":"noun","senses":[{"en":"a very small amount","cn":"一点点；很少量；丝毫","ex":{"en":"She hadn't changed a whit since I'd seen her last.","cn":"自从我上次见到她以来，她一点也没变。"}},{"en":"connected with Whitsun","cn":"圣灵降临节的；圣神降临节的","ex":{"en":"Whit Monday","cn":"圣灵降临节后的第一个星期一"},"pos":"adjective"}]}},"whatnot":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"这一类的东西;诸如此类的东西","en":"People sometimes say 'and whatnot' or 'or whatnot' after mentioning one or more things, to refer in a vague way to other things which are similar.","ex":{"en":"The women were there in their jeans and T-shirts and overalls and whatnot","cn":"女人们穿着牛仔裤、T恤、工装裤等等这类衣服在那个地方。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an expression used at the end of a list of things when you do not want to give the names of everything","cn":"诸如此类的东西﹐等等〔用于不想一一列举时〕"}]},"vocab":{"pos":"n","senses":[{"en":"Whatnot is another word for odds and ends. Whatnot also means etcetera, so it often comes at the end of a list. On top of a dresser, there might be souvenirs, snow globes, a collection of porcelain pigs, and whatnot ."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41whatnot.mp3","us":"media/ldoce/hwd/ame/c/whatnot.mp3"},"examples":[{"en":"It's a new firm. They make toys and whatnot.","cn":"这是家新的公司。他们制作玩具和别的小玩意儿。"},{"en":"Put your bags, cases, and whatnot in the back of the car.","cn":"把你的袋子﹑盒子等等放到汽车后面。"}],"oxford":{"phon":"ˈwɒtnɒt","pos":"noun","senses":[{"en":"used when you are referring to something, but are not being exact and do not mention its name","cn":"（由于拿不准而不指名）某种东西，不可名状的东西","ex":{"en":"It's a new firm. They make toys and whatnot.","cn":"这是家新的公司。他们制作玩具和别的小玩意儿。"}}]}},"whinny":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(马)嘶鸣","en":"When a horse whinnies, it makes a series of high-pitched sounds, usually not very loudly.","ex":{"en":"The girl's horse whinnied.","cn":"那个女孩的马咴儿咴儿地叫着。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a horse whinnies, it makes a high sound 〔","cn":"马〕嘶叫﹐欢嘶"}]},"vocab":{"pos":"n v","senses":[{"en":"A cow moos, a dog barks, a rooster crows, and a horse whinnies. Whinny is both a noun and a verb. As a noun, it's the sound a horse makes. As a verb, it's the horse making the sound."}]},"media":{"uk":"media/ldoce/hwd/bre/5/whinny0205.mp3","us":"media/ldoce/hwd/ame/7/whinny.mp3"},"oxford":{"phon":"ˈwɪni","pos":"noun","senses":[{"en":"a high noise that horses make","cn":"马嘶"},{"en":"to make a quiet neigh","cn":"轻声嘶鸣","pos":"verb"}]}},"whodunit":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a book, film etc about a murder case, in which you do not find out who killed the person until the end","cn":"悬疑破案[侦探]故事[小说﹐电影]"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41whodunit.mp3","us":"media/ldoce/hwd/ame/4/laadwhodunit.mp3"}},"wharf":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"码头","en":"A wharf is a platform by a river or the sea where ships can be tied up."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a structure that is built out into the water so that boats can stop next to it","cn":"码头"}]},"vocab":{"pos":"n v","senses":[{"en":"A wharf is a platform built on the shore that extends over the surface of the water. On the wharf , you saw people preparing to set sail."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld44wharf.mp3","us":"media/ldoce/hwd/ame/7/ld44wharf.mp3"},"oxford":{"phon":"wɔːf","pos":"noun","senses":[{"en":"a flat structure built next to the sea or a river where boats can be tied up and goods unloaded","cn":"码头"}]}},"whorl":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(指纹等的)涡，螺旋状","en":"A whorl is a spiral shape, for example the pattern on the tips of your fingers.","ex":{"en":"He stared at the whorls and lines of her fingertips.","cn":"他盯着她指尖的涡纹和流纹。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a pattern made of a line that curls out in circles that get bigger and bigger","cn":"涡﹔螺旋状"},{"en":"a circular pattern of leaves or flowers on a stem 〔","cn":"茎部的叶或花的〕轮生体"}]},"vocab":{"pos":"n","senses":[{"en":"Whorl describes something that looks like loops — a strand of curly hair that boings back up when you pull in then let it go, a corkscrew, even the track of a roller coaster that spins you in every direction."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41whorl.mp3","us":"media/ldoce/hwd/ame/9/whorl.mp3"},"examples":[{"en":"the whorls on your fingertips","cn":"你指纹的涡"}],"oxford":{"phon":"wɜːl","pos":"noun","senses":[{"en":"a pattern made by a curved line that forms a rough circle, with smaller circles inside bigger ones","cn":"螺旋状图案；螺纹","ex":{"en":"the whorls on your fingertips","cn":"指纹的涡"}},{"en":"a ring of leaves, flowers, etc. around the stem of a plant","cn":"轮，轮生体（环生于植物茎部的叶、花等）","lab":"specialist"}]}},"whorehouse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 brothel","en":"A whorehouse is the same as a brothel ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place where men can pay to have sex","cn":"妓院﹐窑子"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41whorehouse.mp3","us":"media/ldoce/hwd/ame/c/whorehouse.mp3"},"oxford":{"phon":"ˈhɔːhaʊs","pos":"noun","senses":[{"en":"a brothel (= a place where people pay to have sex)","cn":"妓院"}]}},"wheeze":{"collins":{"senses":[{"pos":"VERB 动词","cn":"喘息;气喘吁吁","en":"If someone wheezes, they breathe with difficulty and make a whistling sound.","ex":{"en":"He had quite serious problems with his chest and wheezed and coughed all the time","cn":"他的胸部问题很严重，总是气喘，还不停地咳嗽。"}},{"pos":"N-COUNT 可数名词","cn":"妙招；小窍门；玩笑；小伎俩","en":"A wheeze is a clever idea, joke, or trick.","ex":{"en":"He came up with what seemed like a clever wheeze.","cn":"他提出了一个看起来还不错的主意。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take air into your lungs and send it out again","cn":""},{"en":"to breathe out slowly and make a noise that shows you are disappointed, tired, relieved etc","cn":""},{"en":"to breathe quickly and noisily through your mouth, because you have been using a lot of effort","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/wheeze_v0205.mp3","us":"media/ldoce/hwd/ame/a/wheeze1.mp3"},"examples":[{"en":"‘I have a chest infection,’ she wheezed. “","cn":"我胸部受到了感染。”她呼哧呼哧地说。"},{"en":"He was coughing and wheezing all night.","cn":"他整夜又咳嗽又喘。"}],"oxford":{"phon":"wiːz","pos":"verb","senses":[{"en":"to breathe noisily and with difficulty","cn":"喘；喘息；喘鸣","ex":{"en":"He was coughing and wheezing all night.","cn":"他整夜又咳嗽又喘。"}},{"en":"the high, whistling sound that your chest makes when you cannot breathe easily","cn":"喘息声；喘鸣声；呼吸发出的哨音；呼哧呼哧声","pos":"noun"},{"en":"a clever trick or plan","cn":"花招；计谋","lab":"British English, old-fashioned, informal，，，，","ex":{"en":"He came up with a clever wheeze.","cn":"他灵机一动，想出了一个喘息的办法。"},"pos":"noun"}]}},"whelp":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"幼兽(尤指幼犬或狼崽)","en":"A whelp is a young animal, especially a young dog or wolf."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a young animal, especially a dog or lion","cn":"幼兽〔尤指狗崽或幼狮〕"},{"en":"if a dog or lion whelps, it gives birth 〔","cn":"狗﹑狮〕产崽"}]},"vocab":{"pos":"n v","senses":[{"en":"It doesn't sound as cute as \"puppy,\" but whelp means the same thing: a baby dog or wolf. This can also be a verb, as in \"The mama poodle whelped six whelps .\""}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41whelp.mp3","us":"media/ldoce/hwd/ame/d/whelp.mp3"},"oxford":{"phon":"welp","pos":"noun","senses":[{"en":"a young animal of the dog family; a puppy or cub","cn":"小狗；幼犬；（犬科动物的）幼兽"},{"en":"to give birth to a puppy or puppies","cn":"下（崽）；产（仔）","pos":"verb"}]}},"whoop":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(高兴地)大喊，大叫","en":"If you whoop, you shout loudly in a very happy or excited way.","ex":{"en":"She whoops with delight at a promise of money.","cn":"她因为有可能获得一笔钱而高兴得大叫。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get pleasure from doing something","cn":""},{"en":"to enjoy doing something, especially something that you do regularly or for a long time","cn":""},{"en":"to enjoy doing something very much and get a lot of pleasure out of it","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/whoop0205.mp3","us":"media/ldoce/hwd/ame/f/whoop.mp3"},"examples":[{"en":"whoops of delight","cn":"高兴的喊叫"},{"en":"Hundreds of people ran past them, whooping joyously.","cn":"数百人大声欢呼着从他们身边跑过。"}],"oxford":{"phon":"wuːp","pos":"noun","senses":[{"en":"a loud shout expressing joy, excitement, etc.","cn":"（高兴、激动等时的）高喊，大叫","ex":{"en":"whoops of delight","cn":"高兴的喊叫"}},{"en":"to shout loudly because you are happy or excited","cn":"（因高兴或激动）高喊，喊叫","ex":{"en":"He whooped for joy as the ball hit the back of the net.","cn":"当球击中球网时，他高兴地欢呼起来。"},"pos":"verb"}]}},"whizz":{"collins":{"senses":[{"pos":"VERB 动词","cn":"飞驰;嗖嗖地移动","en":"If something whizzes somewhere, it moves there very fast.","ex":{"en":"Stewart felt a bottle whizz past his head","cn":"斯图尔特感觉有个瓶子从他头上嗖地一下飞了过去。"}},{"pos":"N-COUNT 可数名词","cn":"高手;能手","en":"If you are a whizz at something, you are very good at it.","ex":{"en":"Simon's a whizz at card games.","cn":"西蒙是纸牌高手。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to go somewhere as fast as you can","cn":""},{"en":"to go somewhere very quickly because you are in a hurry","cn":""},{"en":"to travel or go somewhere extremely quickly","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdewhizz.mp3","us":"media/ldoce/hwd/ame/9/amelasdewhizz.mp3"},"examples":[{"en":"He whizzed down the road on his motorbike.","cn":"他骑着摩托车呼啸着沿路绝尘而去。"},{"en":"A bullet whizzed past my ear.","cn":"一颗子弹嗖的一声从我耳边飞过。"}],"oxford":{"phon":"wɪz","pos":"verb","senses":[{"en":"to move very quickly, making a high, continuous sound","cn":"嗖嗖地移动；飞速行驶","g":"[intransitive]","ex":{"en":"A bullet whizzed past my ear.","cn":"一颗子弹嗖的一声从我耳边飞过。"}},{"en":"to do something very quickly","cn":"快速地做；匆匆地干","g":"[intransitive]","ex":{"en":"She whizzed through the work.","cn":"她麻利地把活干完了。"}},{"en":"a person who is very good at something","cn":"能手；善于…的人","ex":{"en":"She's a whizz at crosswords.","cn":"她填纵横字谜很在行。"},"pos":"noun"}]}},"whistle-blower":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"告发者;检举者","en":"A whistle-blower is someone who finds out that the organization they are working for is doing something immoral or illegal and tells the authorities or the public about it.","ex":{"en":"He has been a prominent victim of alleged witch-hunts against whistle-blowers in the NHS.","cn":"他成了英国国民保健制度下所谓追查报复检举者行动的典型牺牲品。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who tells people in authority or the public about dishonest or illegal practices at the place where they work","cn":"告发者﹐告密者﹔检举者"}]},"media":{"uk":"media/ldoce/hwd/bre/a/whistle_blower0205.mp3","us":"media/ldoce/hwd/ame/6/laadwhistle-blower.mp3"},"oxford":{"phon":"ˈwɪsl bləʊə(r)","pos":"noun","senses":[{"en":"a person who informs people in authority or the public that the company they work for is doing something wrong or illegal","cn":"（公司等处）检举揭发舞弊内情的人"}]}},"wholly":{"collins":{"senses":[{"pos":"ADV 副词","cn":"完全地;完整地","en":"You use wholly to emphasize the extent or degree to which something is the case.","ex":{"en":"While the two are only days apart in age they seem to belong to wholly different generations","cn":"尽管这两人年龄上只相差几天，他们却好像是属于完全不同时代的人。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"say this when you strongly agree with something or approve of something, or to emphasize strong adjectives","cn":""},{"en":"use this especially to say that you have completely understood something or have everything that you need","cn":""},{"en":"use this especially to show that you completely disagree with something or that you are very annoyed about it","cn":""}]},"vocab":{"pos":"adv","senses":[{"en":"Wholly is an adverb that means \"entirely.\" If a story is wholly inaccurate, no part of it is true."}]},"media":{"uk":"media/ldoce/hwd/bre/b/wholly0205.mp3","us":"media/ldoce/hwd/ame/c/holy.mp3"},"examples":[{"en":"The government is not wholly to blame for the recession.","cn":"这次衰退不能完全怨政府。"},{"en":"wholly inappropriate behaviour","cn":"完全失当的行为"}],"oxford":{"phon":"ˈhəʊlli","pos":"adverb","senses":[{"en":"completely","cn":"完全；全面；整体地","ex":{"en":"wholly inappropriate behaviour","cn":"完全失当的行为"}}]}},"whitish":{"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"发白的;苍白的","en":"Whitish means very pale and almost white in colour.","ex":{"en":"...a whitish dust.","cn":"发白的灰尘"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"almost white in colour","cn":"发白的﹐带白色的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/whitish0205.mp3","us":"media/ldoce/hwd/ame/c/laadwhitish.mp3"},"examples":[{"en":"a bird with a whitish throat","cn":"白喉鸟"}],"oxford":{"phon":"ˈwaɪtɪʃ","pos":"adjective","senses":[{"en":"fairly white in colour","cn":"发白的；稍白的","ex":{"en":"a bird with a whitish throat","cn":"白喉鸟"}}]}},"whippet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小灵狗(腿长，瘦小，可用于赛狗)","en":"A whippet is a small thin dog with long legs. Some whippets are used for racing."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small thin racing dog like a greyhound","cn":"小灵犬〔一种小型赛犬〕"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41whippet.mp3","us":"media/ldoce/hwd/ame/9/whippet.mp3"},"oxford":{"phon":"ˈwɪpɪt","pos":"noun","senses":[{"en":"a small, thin dog, similar to a greyhound, that can run very fast and is often used for racing","cn":"惠比特犬（类似灵缇，常用于赛狗）"}]}},"wheelbase":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(汽车或其他交通工具前后轮之间的)轴距","en":"The wheelbase of a car or other vehicle is the distance between its front and back wheels."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the distance between the front and back axle s of a vehicle 〔","cn":"车辆前后轴的〕轴距"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41wheelbase.mp3","us":"media/ldoce/hwd/ame/a/wheelbase.mp3"},"oxford":{"phon":"ˈwiːlbeɪs","pos":"noun","senses":[{"en":"the distance between the front and back wheels of a car or other vehicle","cn":"（汽车或其他机动车辆的）轴距；（机车的）轮组定距","ex":{"en":"a long/short/standard wheelbase","cn":"长/短/标准轴距"}}]}},"wholesaler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"批发商","en":"A wholesaler is a person whose business is buying large quantities of goods and selling them in smaller amounts, for example to shops."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a company or person that sells goods to the public in a shop - used especially in business contexts","cn":""},{"en":"a person or company that sells goods in large quantities and at low prices, especially to other companies that then sell the goods to the public","cn":""},{"en":"a person or company that buys and sells large quantities of goods such as wine, or basic materials such as coal and wood","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/wholesaler0205.mp3","us":"media/ldoce/hwd/ame/1/wholesaler.mp3"},"examples":[{"en":"fruit and vegetable wholesalers","cn":"水果和蔬菜批发商"}],"oxford":{"phon":"ˈhəʊlseɪlə(r)","pos":"noun","senses":[{"en":"a person or company that sells goods in large quantities to other companies or people who then sell them to the public","cn":"批发商","ex":{"en":"fruit and vegetable wholesalers","cn":"水果和蔬菜批发商"}}]}},"whippersnapper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"自以为是的人;妄自尊大的人","en":"If you refer to a young person as a whippersnapper, you disapprove of them because you think that they are behaving more confidently than they should.","ex":{"en":"...this bunch of irresponsible young whippersnappers.","cn":"这群不负责任自以为是的年轻人"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a young person who is too confident and does not show enough respect to older people","cn":"妄自尊大的年轻人﹐傲慢无礼的小子"}]},"vocab":{"pos":"n","senses":[{"en":"A whippersnapper is someone who is younger than you are but also irritatingly overconfident and impertinent, like your little smart aleck cousin."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41whippersnapper.mp3","us":"media/ldoce/hwd/ame/3/whippersnapper.mp3"},"oxford":{"phon":"ˈwɪpəsnæpə(r)","pos":"noun","senses":[{"en":"a young and unimportant person who behaves in a way that others think is too confident and rude","cn":"狂妄小子"}]}},"whip":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鞭子","en":"A whip is a long thin piece of material such as leather or rope, fastened to a stiff handle. It is used for hitting people or animals."},{"pos":"VERB 动词","cn":"鞭打(人或动物)","en":"If someone whips a person or animal, they beat them or hit them with a whip or something like a whip.","ex":{"en":"Eyewitnesses claimed Mr Melton whipped the horse up to 16 times","cn":"目击证人称梅尔顿先生抽打了这匹马16鞭之多。"}},{"pos":"VERB 动词","cn":"(风等)猛烈地抽打","en":"If something, for example the wind, whips something, it strikes it sharply.","ex":{"en":"A terrible wind whipped our faces","cn":"狂风抽打着我们的脸。"}},{"pos":"VERB 动词","cn":"(在外力作用下)猛然移动","en":"If something flexible whips in a particular way, it moves sharply when it is affected by a force, for example by the wind.","ex":{"en":"Blond strands of hair whipped in the wind.","cn":"缕缕金发在风中飘扬。"}},{"pos":"VERB 动词","cn":"快速移开;快速拿走","en":"If someone whips something out or whips it off, they take it out or take it off very quickly and suddenly.","ex":{"en":"Bob whipped out his notebook","cn":"鲍勃迅速掏出他的笔记本。"}},{"pos":"VERB 动词","cn":"迅速地移动","en":"If something or someone whips somewhere, they move there or go there very quickly.","ex":{"en":"The wind out here is whipping along at about 30 miles an hour","cn":"在这里，大风以每小时大约30英里的速度刮着。"}},{"pos":"VERB 动词","cn":"搅打(奶油或鸡蛋等)","en":"When you whip something liquid such as cream or an egg, you stir it very fast until it is thick or stiff.","ex":{"en":"Whip the cream until thick","cn":"搅打奶油直到它变黏稠。"}},{"pos":"VERB 动词","cn":"(故意)激起(情绪)","en":"If you whip people into an emotional state, you deliberately cause and encourage them to be in that state.","ex":{"en":"He could whip a crowd into hysteria","cn":"他能让一群人变得歇斯底里。"}},{"pos":"N-COUNT 可数名词","cn":"组织秘书，党鞭（维持党纪并督导该党议员出席议会重要议题的讨论和表决的人）","en":"A whip is a member of a political party in a parliament or legislature who is responsible for making sure that party members are present to vote on important issues and that they vote in the appropriate way."},{"pos":"PHRASE 短语","cn":"控制权;主导地位","en":"If you have the whip hand, you have power over someone else in a particular situation.","ex":{"en":"These days the shopper has the whip hand, and will not buy if stores fail to lower their prices.","cn":"如今购物者占主导地位，如果商店不降价，他们是不会买的。"}},{"pos":"","cn":"","en":"a fair crack of the whip→see: ;"},{"pos":"","cn":"","en":"相关词组：whip up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone worried, confused etc, especially only for a short time","cn":""},{"en":"make people feel interested, jealous etc","cn":""},{"en":"to make people have a strong interest in something or strong feelings, such as anger, fear, dislike etc","cn":""}]},"collocations":{"phrases":["ADJ. driving, riding | bull, horse","VERB + WHIP crack, flick He cracked the whip and the horse leapt forward.","VERB + WHIP crack A hound yelped briefly as a whip cracked.","PHRASES the crack of a whip"]},"media":{"img":["media/ldoce/img/whip.jpg","media/thumb/whip.jpg"],"uk":"media/ldoce/hwd/bre/e/brelasdewhip.mp3","us":"media/ldoce/hwd/ame/f/whip1.mp3"},"examples":[{"en":"She whipped up a delicious lunch for us in 15 minutes.","cn":"她用了 15 分钟就给我们备好了一顿可口的午餐。"},{"en":"The team whipped its opponents by 35 points.","cn":"这个队以 35 分的优势轻松击败对手。"}],"oxford":{"phon":"wɪp","pos":"verb","senses":[{"en":"to hit a person or an animal hard with a whip, as a punishment or to make them go faster or work harder","cn":"鞭打；鞭策；以鞭打责罚；鞭笞","g":"[transitive]","ex":{"en":"He was taken back to the jail and soundly whipped.","cn":"他被带回监狱，狠狠捱了一顿鞭子。"}},{"en":"to move, or make something move, quickly and suddenly or violently in a particular direction","cn":"（使朝某一方向）猛然移动","g":"[intransitive, transitive]","ex":{"en":"A branch whipped across the car window.","cn":"一条树枝突然划过车窗。"}},{"en":"to remove or pull something quickly and suddenly","cn":"（突然迅速地）除去，拉动，抽出","g":"[transitive]","ex":{"en":"She whipped the mask off her face.","cn":"她唰地一下子把脸上的面具摘掉了。"}},{"en":"to mix cream, etc. very quickly until it becomes stiff","cn":"搅打（奶油等）","g":"[transitive]","ex":{"en":"Serve the pie with whipped cream.","cn":"馅饼得配搅打奶油。"}},{"en":"to defeat somebody very easily in a game","cn":"（在比赛中）轻易击败，一举战胜","g":"[transitive]","lab":"North American English, informal，，","ex":{"en":"The team whipped its opponents by 35 points.","cn":"这个队以 35 分的优势轻松击败对手。"}},{"en":"to steal something","cn":"偷；盗窃","g":"[transitive]","lab":"British English, informal，，"},{"en":"a long, thin piece of rope or leather, attached to a handle, used for hitting animals or people, to make them move, or move faster, or as a punishment","cn":"鞭子","g":"[countable]","ex":{"en":"He cracked his whip and the horse leapt forward.","cn":"他甩了个响鞭，马儿就奋蹄向前奔去。"},"pos":"noun"},{"en":"an official in a political party who is responsible for making sure that the party's MPs attend and vote in important debates in a parliament","cn":"党鞭（政党中负责督导本党议员参与议会重大问题辩论并投票的组织秘书）","g":"[countable]","ex":{"en":"the chief whip","cn":"首席党鞭"},"pos":"noun"},{"en":"a written instruction telling the MPs of a political party how to vote on a particular issue","cn":"（政党发给党员的）投票通知书，投票指示","g":"[countable]","lab":"British English","pos":"noun"},{"en":"the fact of being an MP belonging to a particular party, with the duties and rights associated with that","cn":"（属于某党派的）议员资格","g":"[singular]","lab":"British English","ex":{"en":"He resigned the Tory whip and sat as an independent.","cn":"他辞去保守党议员，成为无党派议员。"},"pos":"noun"},{"en":"a sweet dish made from cream, eggs, sugar and fruit mixed together","cn":"搅打奶油甜食（用奶油、鸡蛋、糖和水果搅打而成）","g":"[uncountable, countable]","pos":"noun"}]}},"wham":{"collins":{"senses":[{"pos":"EXCLAM 感叹语","cn":"(指突然或剧烈的声响)砰，嘭","en":"You use wham to indicate that something happens suddenly or forcefully.","ex":{"en":"Then I met someone and wham, bam, I was completely in love","cn":"然后我遇上了一个人，嘭的一下，我就坠入了爱河。"}}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"used to describe the sound of something suddenly hitting something else very hard","cn":"砰﹐嘭〔形容某物突然撞击他物的声音〕"},{"en":"used to express the idea that something very unexpected suddenly happens 〔","cn":"表示意外的事情突然发生〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/wham_interject0205.mp3","us":"media/ldoce/hwd/ame/c/wham.mp3"},"examples":[{"en":"I saw him yesterday and — wham! — I realized I was still in love with him.","cn":"我昨天看到他了。我猛地一下子意识到我仍然爱着他。"},{"en":"The bombs went down — wham! — right on target.","cn":"炸弹落了下来，砰！正好击中目标。"}],"oxford":{"phon":"wæm","pos":"exclamation","senses":[{"en":"used to represent the sound of a sudden, loud hit","cn":"（突然的重击声）砰，嘭","ex":{"en":"The bombs went down—wham!—right on target.","cn":"炸弹落了下来，砰！正好击中目标。"}},{"en":"used to show that something that is unexpected has suddenly happened","cn":"（表示意外的事情突然发生）","ex":{"en":"I saw him yesterday and—wham!—I realized I was still in love with him.","cn":"我昨天看到他了。我猛地一下子意识到我仍然爱着他。"}},{"en":"a British pop group formed in 1982, which group was very successful in the 1980s, with songs including Wake Me Up Before You Go-Go (1984) and I'm Your Man (1985). Its main singer was George Michael, who left the group to begin a career on his own in 1986.","cn":"成立于1982年的英国流行乐队，该乐队在1980年代非常成功，歌曲包括Wake Me Up Before You Go-Go（1984）和I'm Your Man（1985）。它的主要歌手是乔治·迈克尔（George Michael），他于1986年离开乐队开始了自己的职业生涯。","pos":""}]}},"whopper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"弥天大谎","en":"If you describe a lie as a whopper, you mean that it is very far from the truth.","ex":{"en":"...the biggest whopper the president told.","cn":"总统撒的弥天大谎"}},{"pos":"N-COUNT 可数名词","cn":"特别大的物体;庞然大物","en":"If you refer to something as a whopper, you mean that it is an unusually large example of the thing mentioned.","ex":{"en":"As comets go, it is a whopper.","cn":"就彗星而言，它可是个庞然大物。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"very big and impressive","cn":""},{"en":"very big and impressive - used especially in literature","cn":""},{"en":"extremely big","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/whopper0205.mp3","us":"media/ldoce/hwd/ame/5/whopper.mp3"},"examples":[{"en":"She's told some whoppers about her past.","cn":"关于她的过去，她说了些谎话。"},{"en":"Pete has caught a whopper (= a large fish).","cn":"皮特捕到了一条特大的鱼。"}],"oxford":{"phon":"ˈwɒpə(r)","pos":"noun","senses":[{"en":"something that is very big for its type","cn":"特大的（或硕大的）东西","ex":{"en":"Pete has caught a whopper (= a large fish).","cn":"皮特捕到了一条特大的鱼。"}},{"en":"a lie","cn":"谎言；瞎话","ex":{"en":"She's told some whoppers about her past.","cn":"关于她的过去，她说了些谎话。"}}]}},"whiting":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"牙鳕","en":"A whiting is a black and silver fish that lives in the sea.","ex":{"en":"...fishing boats which normally catch a mix of cod, haddock and whiting.","cn":"通常会捕捞到鳕鱼、黑线鳕和牙鳕的渔船"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a black and silver fish that lives in the sea and can be eaten","cn":"牙鳕〔一种可食用的海鱼〕"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41whiting.mp3","us":"media/ldoce/hwd/ame/b/whiting1.mp3"},"oxford":{"phon":"ˈwaɪtɪŋ","pos":"noun","senses":[{"en":"a small sea fish that is white inside and used for food","cn":"牙鳕（小海鱼，肉白色，可食用）"}]}},"whisky":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"(尤指产于苏格兰、由大麦或黑麦酿制的)威士忌酒","en":"Whisky is a strong alcoholic drink made, especially in Scotland, from grain such as barley or rye.","ex":{"en":"...a bottle of whisky.","cn":"一瓶威士忌"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong alcoholic drink made from grain, or a glass of this","cn":"威士忌酒﹔一杯威士忌酒"}]},"collocations":{"phrases":["ADJ. double, large | single, small | stiff | neat, straight I'll have my whisky straight, please. | excellent, fine, good a fine malt whisky","QUANT. dash, drop, nip He added a dash of whisky to his coffee. | measure, shot, tot She poured herself a large tot of whisky. | bottle, fla","VERB + WHISKY drink Do you drink whisky? | have He had a whisky on the rocks. | pour (sb) | sip | gulp, swig | down, finish | distil, produc","WHISKY + NOUN drinker | bottle, decanter | glass, tumbler | chaser He ordered a beer with a whisky chaser (= a small glass of whisky drunk a","PHRASES whisky on the rocks (= with ice)"]},"media":{"uk":"media/ldoce/hwd/bre/d/whisky0205.mp3","us":"media/ldoce/hwd/ame/c/amelasdewhisky.mp3"},"examples":[{"en":"Two whiskies, please.","cn":"请来两杯威士忌。"},{"en":"a whisky and soda","cn":"一杯加苏打水的威士忌"}],"oxford":{"phon":"ˈwɪski","pos":"noun","senses":[{"en":"a strong alcoholic drink made from malted grain. It is sometimes drunk with water and/or ice.","cn":"威士忌","g":"[uncountable, countable]","ex":{"en":"a bottle of whisky","cn":"一瓶威士忌"}},{"en":"a glass of whisky","cn":"一杯威士忌","g":"[countable]","lab":"British English","ex":{"en":"a whisky and soda","cn":"一杯加苏打水的威士忌"}}]}},"wholesome":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指不包含不道德的性内容)健康的，有益身心的","en":"If you describe something as wholesome, you approve of it because you think it is likely to have a positive influence on people's behaviour or mental state, especially because it does not involve anything sexually immoral.","ex":{"en":"...good, wholesome fun.","cn":"健康有益的娱乐"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(食物)有益健康的","en":"If you describe food as wholesome, you approve of it because you think it is good for your health.","ex":{"en":"...fresh, wholesome ingredients","cn":"新鲜的、有利于健康的烹饪材料"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"wholesome behaviour, activities, books etc are considered good and suitable for everyone, especially because they do not involve sex or swearing","cn":""},{"en":"not offensive to anyone, especially because of not being about sex","cn":""},{"en":"if something is good for you or is good for your health , it makes you more healthy or stops you getting ill","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Anything wholesome is good for you. Hopscotch is in most cases a wholesome game, since you can't get into much trouble while hopping up and down on the concrete."}]},"media":{"uk":"media/ldoce/hwd/bre/1/wholesome0205.mp3","us":"media/ldoce/hwd/ame/1/wholesome.mp3"},"examples":[{"en":"It was clean wholesome fun.","cn":"这是健康有益的玩乐。"},{"en":"fresh, wholesome food","cn":"有益健康的新鲜食品"}],"oxford":{"phon":"ˈhəʊlsəm","pos":"adjective","senses":[{"en":"good for your health","cn":"有益健康的","ex":{"en":"fresh, wholesome food","cn":"有益健康的新鲜食品"}},{"en":"morally good; having a good moral influence","cn":"有道德的；有良好道德影响的","ex":{"en":"It was clean wholesome fun.","cn":"这是健康有益的玩乐。"}}]}},"wheelwright":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(制作和修理木制轮子及手推车、马车、门等其他木制品的)轮匠","en":"A wheelwright is someone who makes and repairs wooden wheels and other wooden things such as carts, carriages, and gates."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job was to make and repair the wooden wheels of vehicles pulled by horses in the past 〔","cn":"旧时马车的〕车轮修造工"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41wheelwright.mp3","us":"media/ldoce/hwd/ame/6/wheelwright.mp3"},"oxford":{"phon":"ˈwiːlraɪt","pos":"noun","senses":[{"en":"a person whose job is making and repairing wheels, especially wooden ones","cn":"车轮修造工（尤指木轮的）"}]}},"whip-round":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"凑钱;凑份子","en":"When a group of people have a whip-round, money is collected from each person so that it can be used to buy something for all of them or for someone they all know."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to give some of the money that is needed to pay for something","cn":""},{"en":"to give an amount of money that when added to money given by other people, can be used to pay for something useful","cn":""},{"en":"to collect money from each of the people in a group, especially in order to buy something for someone","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/whip_round0205.mp3","us":"media/ldoce/hwd/ame/9/amelasdewhip-round.mp3"},"examples":[{"en":"We had a whip-round to pay for a taxi to the railway station.","cn":"我们凑钱坐出租车去火车站。"}],"oxford":{"phon":"ˈwɪp raʊnd","pos":"noun","senses":[{"en":"if a group of people have a whip-round, they all give money so they can buy something for somebody or pay for something","cn":"凑份子","ex":{"en":"We had a whip-round at the office to buy her a leaving present.","cn":"我们在办公室兜兜转转，给她买了一份临别礼物。"}}]}},"whey":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"乳清","en":"Whey is the watery part of sour milk that is separated from the thick part called curds, for example when you are making cheese."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the watery liquid that is left after the solid part has been removed from sour milk","cn":"乳清"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41whey.mp3","us":"media/ldoce/hwd/ame/8/way1.mp3"},"oxford":{"phon":"weɪ","pos":"noun","senses":[{"en":"the thin liquid that is left from milk after the solid part (called curds) has been removed","cn":"乳清，乳水（酸奶中的凝乳去掉后剩下的含水成分）"}]}},"whopping":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"异常大的;庞大的","en":"If you describe an amount as whopping, you are emphasizing that it is large.","ex":{"en":"The Russian leader won a whopping 89.9 percent yes vote","cn":"这位俄罗斯领导人赢得了89.9%的高票支持。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this about an amount, number etc that is so large that it cannot be easily measured","cn":""},{"en":"extremely large","cn":""},{"en":"use this about numbers or amounts, especially of money, that are extremely and surprisingly large","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41whopping.mp3","us":"media/ldoce/hwd/ame/a/whopping.mp3"},"examples":[{"en":"The company made a whopping 75 million dollar loss.","cn":"公司遭受了 7 500 万元的巨额损失。"},{"en":"a whopping fee","cn":"一笔巨额费用"}],"oxford":{"phon":"ˈwɒpɪŋ","pos":"adjective","senses":[{"en":"very big","cn":"很大的；巨大的","ex":{"en":"The company made a whopping 75 million dollar loss.","cn":"公司遭受了 7 500 万美元的巨额损失。"}}]}},"whistleblower":{"lemma":"whistle-blower"},"whimper":{"collins":{"senses":[{"pos":"VERB 动词","cn":"抽泣;呜咽;啜泣","en":"If someone whimpers, they make quiet unhappy or frightened sounds, as if they are about to start crying.","ex":{"en":"She lay at the bottom of the stairs, whimpering in pain","cn":"她躺在楼梯底部，痛得呜咽着。"}},{"pos":"VERB 动词","cn":"抽噎着说;哀诉","en":"If someone whimpers something, they say it in an unhappy or frightened way.","ex":{"en":"'Let me go,' she whimpered. 'You're hurting me.'","cn":"“放开我，”她哀诉道，“你弄痛我了。”"}},{"pos":"PHRASE 短语","cn":"雷声大，雨点小","en":"If you say that something happens not with a bang but a whimper, you mean that it is less effective or exciting than was expected or intended.","ex":{"en":"He bowed out of world politics not with a bang but a whimper","cn":"他黯然退出了世界政坛。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to produce tears from your eyes","cn":""},{"en":"to cry a lot and for a long time","cn":""},{"en":"to be crying","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To whimper is to make a low, pitiful whining sound. If you've ever heard a sick puppy cry, you know what it means to whimper ."}]},"collocations":{"phrases":["ADV. softly The dog whimpered softly. | pathetically","VERB + WHIMPER begin to, start to | hear sb","PREP. with The boy was whimpering with pain.","PHRASES whimper like a child He stirred in her arms, whimpering like a child."]},"media":{"uk":"media/ldoce/hwd/bre/1/whimper0205.mp3","us":"media/ldoce/hwd/ame/9/whimper.mp3"},"examples":[{"en":"The child was lost and began to whimper.","cn":"那孩子迷了路，抽抽搭搭地哭起来。"},{"en":"‘Don't leave me alone,’ he whimpered. “","cn":"别丢下我不管。”他呜咽着说。"}],"oxford":{"phon":"ˈwɪmpə(r)","pos":"verb","senses":[{"en":"to make low, weak crying noises; to speak in this way","cn":"抽泣；呜咽；啜泣；泣诉；抽搭着说","ex":{"en":"The dog whimpered softly.","cn":"狗轻声呜咽着。"}},{"en":"a low, weak sound that a person or an animal makes when they are hurt, frightened or sad","cn":"抽泣；呜咽声","lab":"figurative","ex":{"en":"The puppy gave a little whimper of fear.","cn":"小狗害怕地小声呜咽。"},"pos":"noun"}]}},"whacking":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(表示强调)很大的,巨大的","en":"You can use whacking to emphasize how big something is.","ex":{"en":"The supermarkets may be making whacking profits.","cn":"超市可能都在赚大钱。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"very big","cn":"极大的﹐巨大的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/whacking0205.mp3","us":"media/ldoce/hwd/ame/a/ld41whacking.mp3"},"examples":[{"en":"They were fined a whacking £100 000.","cn":"他们被罚了 10 万英镑的巨款。"},{"en":"a whacking great hole in the roof","cn":"房顶上一个巨大的窟窿"}],"oxford":{"phon":"ˈwækɪŋ","pos":"adjective","senses":[{"en":"used to emphasize how big or how much something is","cn":"（强调体积或数额）巨大的，极大的","ex":{"en":"a whacking great hole in the roof","cn":"房顶上一个巨大的窟窿"}}]},"base":"whack"},"whisper":{"collins":{"senses":[{"pos":"VERB 动词","cn":"低声说;悄悄说;耳语","en":"When you whisper, you say something very quietly, using your breath rather than your throat, so that only one person can hear you.","ex":{"en":"'Keep your voice down,' I whispered","cn":"我轻声说：“小声点儿。”"}},{"pos":"VERB 动词","cn":"私下谈论；谣传","en":"If people whisper about a piece of information, they talk about it, although it might not be true or accurate, or might be a secret.","ex":{"en":"Today, we no longer gasp when we hear a teenage girl is pregnant or whisper about unmarried couples who live together","cn":"今天，我们听到未成年少女怀孕时不会再感到惊讶，也不会再去私下谈论谁谁未婚同居。"}},{"pos":"VERB 动词","cn":"发出低沉而轻微的声音；沙沙（或飒飒）作响","en":"If something whispers, it makes a low quiet sound which can only just be heard.","ex":{"en":"The cold breeze moved through the bushes around him, whispering just loud enough to obscure the chanting","cn":"冷飕飕的风吹动着他周边的矮树丛，沙沙声刚好盖过了吟唱的声音。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say something very quietly, using your breath rather than your full voice","cn":""},{"en":"to say something quietly without pronouncing the words clearly","cn":""},{"en":"to say something quietly, especially when you are annoyed but do not want someone to hear you complaining","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Psst! When you speak very quietly, so that hardly anyone can hear, you're whispering , or speaking in a whisper ."}]},"collocations":{"phrases":["ADV. softly | hoarsely, huskily, thickly | fiercely, urgently &lsquo;Come on,&rsquo;he whispered urgently. | brokenly, shakily, unsteadily |","VERB + WHISPER can/could only He could only whisper in reply. | hear sb She heard him whisper her name.","PREP. about I felt that everyone was whispering about me. | against &lsquo;Hush, &rsquo; he whispered against her hair. | through &lsquo;No,","PHRASES whisper sth in/into sb's ear, whisper sweet nothings He held her and whispered sweet nothings in her ear."]},"media":{"uk":"media/ldoce/hwd/bre/4/whisper_n0205.mp3","us":"media/ldoce/hwd/ame/d/whisper1.mp3"},"examples":[{"en":"It was whispered that he would soon die and he did.","cn":"有人私下说他将不久于人世，他果然死了。"},{"en":"Don't you know it's rude to whisper?","cn":"难道你不知道窃窃私语是不礼貌的吗？"}],"oxford":{"phon":"ˈwɪspə(r)","pos":"verb","senses":[{"en":"to speak very quietly to somebody so that other people cannot hear what you are saying","cn":"耳语；低语；私语；小声说","g":"[intransitive, transitive]","ex":{"en":"Don't you know it's rude to whisper?","cn":"难道你不知道窃窃私语是不礼貌的吗？"}},{"en":"to say or suggest something about somebody/something in a private or secret way","cn":"私下说；秘密告诉；悄声暗示","g":"[transitive, often passive]","ex":{"en":"It was whispered that he would soon die and he did.","cn":"有人私下说他将不久于人世，他果然死了。"}},{"en":"to make a soft, quiet sound","cn":"沙沙作响；发飒飒声","g":"[intransitive]","lab":"literary","ex":{"en":"A warm breeze whispered through the trees.","cn":"一阵温暖的微风吹过树林。"}},{"en":"a low, quiet voice or the sound it makes","cn":"耳语（声）；低语（声）；私语（声）","ex":{"en":"‘I love you,’ he said in a whisper.","cn":"“我爱你。”他低声说。"},"pos":"noun"},{"en":"a soft sound","cn":"轻柔的声音","lab":"literary","ex":{"en":"I could hear the whispering of the sea.","cn":"我听见大海在轻声诉说。"},"pos":"noun"},{"en":"a piece of news that is spread by being talked about but may not be true","cn":"传言；谣传","ex":{"en":"I've heard whispers that he's leaving.","cn":"我听到传言，说他要走。"},"pos":"noun"}]}},"whiplash":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(车祸等中造成的)颈部过度屈伸损伤","en":"Whiplash is a neck injury caused by the head suddenly moving forwards and then back again, for example in a car accident.","ex":{"en":"His wife suffered whiplash and shock","cn":"他的妻子颈部过度屈伸受伤且休克。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a neck injury caused when your head moves forward and back again suddenly and violently, especially in a car accident","cn":"挥鞭伤〔尤指车祸造成的颈部过度屈伸损伤〕"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41whiplash.mp3","us":"media/ldoce/hwd/ame/2/whiplash.mp3"},"examples":[{"en":"He was very bruised and suffering from whiplash.","cn":"他满身青肿，而且颈部过度屈伸受伤。"},{"en":"One officer suffered whiplash injuries.","cn":"一名警官颈部受了挥鞭伤。"}],"oxford":{"phon":"ˈwɪplæʃ","pos":"noun","senses":[{"en":"a hit with a whip","cn":"鞭打","g":"[countable, usually singular]","ex":{"en":"Her sharp voice cut the air like a whiplash.","cn":"她刺耳的嗓音像鞭打一般响彻空中。"}},{"en":"a neck injury caused when your head moves forward and back suddenly, especially in a car accident","cn":"挥鞭伤，鞭打损伤（尤指车祸造成的颈部过度屈伸损伤）","g":"[uncountable]","ex":{"en":"He was very bruised and suffering from whiplash.","cn":"他满身青肿，而且颈部受挥鞭伤。"}}]}},"whiskey":{"lemma":"whisky"}});
